#include <stdio.h>

#define N 8

/* 带哨兵的顺序查找：a[0] 留给哨兵，数据存 a[1..n] */
static int seqSearch(int a[], int n, int key)
{
    int i = n;
    a[0] = key;              /* 设哨兵，免去越界判断 */
    while (a[i] != key)
        i--;
    return i;                /* 返回 0 表示查找失败 */
}

int main(void)
{
    int a[N + 1] = {0, 34, 12, 56, 7, 45, 23, 89, 16};
    int keys[3] = {45, 34, 100};
    int i;

    for (i = 0; i < 3; i++) {
        int pos = seqSearch(a, N, keys[i]);
        if (pos == 0)
            printf("key=%d not found\n", keys[i]);
        else
            printf("key=%d found at %d\n", keys[i], pos);
    }
    return 0;
}

#include <stdio.h>

#define N 11

/* 折半查找：返回下标，*cmp 记录比较次数；失败返回 -1 */
static int binSearch(const int a[], int n, int key, int *cmp)
{
    int low = 0, high = n - 1, mid;
    *cmp = 0;
    while (low <= high) {
        mid = low + (high - low) / 2;
        (*cmp)++;
        if (a[mid] == key) return mid;
        if (a[mid] > key) high = mid - 1;
        else              low  = mid + 1;
    }
    return -1;
}

int main(void)
{
    int a[N] = {7, 12, 16, 23, 34, 45, 56, 67, 78, 89, 96};
    int keys[3] = {7, 45, 50};
    int i, cmp;

    for (i = 0; i < 3; i++) {
        int pos = binSearch(a, N, keys[i], &cmp);
        if (pos < 0)
            printf("key=%d not found, cmp=%d\n", keys[i], cmp);
        else
            printf("key=%d found at %d, cmp=%d\n", keys[i], pos, cmp);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct BSTNode {
    int key;
    struct BSTNode *lchild, *rchild;
} BSTNode, *BSTree;

/* 递归插入：成功返回 1，关键字已存在或内存不足返回 0 */
static int bstInsert(BSTree *t, int key)
{
    BSTNode *p;
    if (*t == NULL) {
        p = (BSTNode *)malloc(sizeof(BSTNode));
        if (p == NULL) return 0;
        p->key = key;
        p->lchild = p->rchild = NULL;
        *t = p;
        return 1;
    }
    if (key == (*t)->key)  return 0;
    if (key < (*t)->key)   return bstInsert(&(*t)->lchild, key);
    return bstInsert(&(*t)->rchild, key);
}

/* 中序遍历：应输出递增序列 */
static void inOrder(const BSTree t)
{
    if (t == NULL) return;
    inOrder(t->lchild);
    printf("%d ", t->key);
    inOrder(t->rchild);
}

static int bstSearch(const BSTree t, int key)
{
    if (t == NULL)        return 0;
    if (t->key == key)    return 1;
    if (key < t->key)     return bstSearch(t->lchild, key);
    return bstSearch(t->rchild, key);
}

static void freeTree(BSTree t)
{
    if (t == NULL) return;
    freeTree(t->lchild);
    freeTree(t->rchild);
    free(t);
}

int main(void)
{
    BSTree t = NULL;
    int keys[7] = {45, 23, 67, 12, 34, 56, 78};
    int i;

    for (i = 0; i < 7; i++)
        bstInsert(&t, keys[i]);

    printf("inOrder: ");
    inOrder(t);
    printf("\nsearch 34: %d\n", bstSearch(t, 34));
    printf("search 50: %d\n", bstSearch(t, 50));

    freeTree(t);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct BSTNode {
    int key;
    struct BSTNode *lchild, *rchild;
} BSTNode, *BSTree;

static int bstInsert(BSTree *t, int key)
{
    BSTNode *p;
    if (*t == NULL) {
        p = (BSTNode *)malloc(sizeof(BSTNode));
        if (p == NULL) return 0;
        p->key = key;
        p->lchild = p->rchild = NULL;
        *t = p;
        return 1;
    }
    if (key == (*t)->key) return 0;
    if (key < (*t)->key)  return bstInsert(&(*t)->lchild, key);
    return bstInsert(&(*t)->rchild, key);
}

/* 递归删除关键字为 key 的结点，返回子树新根 */
static BSTree bstDelete(BSTree t, int key)
{
    BSTree p;
    if (t == NULL) return NULL;
    if (key < t->key) {
        t->lchild = bstDelete(t->lchild, key);
    } else if (key > t->key) {
        t->rchild = bstDelete(t->rchild, key);
    } else {                          /* 找到被删结点 */
        if (t->lchild == NULL) {      /* 叶子 或 只有右子树 */
            p = t->rchild;
            free(t);
            return p;
        }
        if (t->rchild == NULL) {      /* 只有左子树 */
            p = t->lchild;
            free(t);
            return p;
        }
        p = t->lchild;                /* 双子树：找中序前驱 */
        while (p->rchild != NULL) p = p->rchild;
        t->key = p->key;              /* 前驱关键字顶替 */
        t->lchild = bstDelete(t->lchild, p->key);
    }
    return t;
}

static void inOrder(const BSTree t)
{
    if (t == NULL) return;
    inOrder(t->lchild);
    printf("%d ", t->key);
    inOrder(t->rchild);
}

static void freeTree(BSTree t)
{
    if (t == NULL) return;
    freeTree(t->lchild);
    freeTree(t->rchild);
    free(t);
}

int main(void)
{
    BSTree t = NULL;
    int keys[8] = {45, 23, 67, 12, 34, 56, 78, 30};
    int i;

    for (i = 0; i < 8; i++)
        bstInsert(&t, keys[i]);

    printf("before:  "); inOrder(t); printf("\n");
    t = bstDelete(t, 12);             /* 叶子 */
    printf("del 12:  "); inOrder(t); printf("\n");
    t = bstDelete(t, 23);             /* 只剩右子树 */
    printf("del 23:  "); inOrder(t); printf("\n");
    t = bstDelete(t, 45);             /* 双子树，用前驱 34 顶替 */
    printf("del 45:  "); inOrder(t); printf("\n");

    freeTree(t);
    return 0;
}

#include <stdio.h>

#define M 13
#define P 13
#define EMPTY -1

int main(void)
{
    int table[M];
    int keys[8] = {19, 14, 23, 1, 68, 20, 84, 27};
    int i, j;

    for (i = 0; i < M; i++) table[i] = EMPTY;

    for (i = 0; i < 8; i++) {
        int h = keys[i] % P;          /* 除留余数 */
        while (table[h] != EMPTY)     /* 冲突则线性探测下一格 */
            h = (h + 1) % M;
        table[h] = keys[i];
    }

    printf("index:");
    for (j = 0; j < M; j++) printf("%4d", j);
    printf("\nvalue:");
    for (j = 0; j < M; j++) {
        if (table[j] == EMPTY) printf("%4s", "-");
        else                   printf("%4d", table[j]);
    }
    printf("\n");
    return 0;
}

#include <stdio.h>

#define M 13
#define P 13
#define EMPTY -1

int main(void)
{
    int table[M];
    int keys[8] = {19, 14, 23, 1, 68, 20, 84, 27};
    int queries[3] = {27, 84, 19};
    int i;

    for (i = 0; i < M; i++) table[i] = EMPTY;
    for (i = 0; i < 8; i++) {
        int h = keys[i] % P;
        while (table[h] != EMPTY) h = (h + 1) % M;
        table[h] = keys[i];
    }

    for (i = 0; i < 3; i++) {
        int key = queries[i];
        int h = key % P, cmp = 0;
        while (table[h] != EMPTY && cmp < M) {
            cmp++;
            if (table[h] == key) {
                printf("key=%d found at %d, cmp=%d\n", key, h, cmp);
                break;
            }
            h = (h + 1) % M;
        }
        if (table[h] == EMPTY)
            printf("key=%d not found, cmp=%d\n", key, cmp);
    }
    return 0;
}

#include <stdio.h>

#define N 7

/* 折半查找，返回比较次数（正数=成功，负数=失败但绝对值是比较次数） */
static int binSearch(const int *a, int n, int key)
{
    int low = 0, high = n - 1, mid, cmp = 0;

    while (low <= high) {
        mid = low + (high - low) / 2;
        cmp++;
        if (a[mid] == key) return cmp;
        if (a[mid] < key) low = mid + 1;
        else high = mid - 1;
    }
    return -cmp;
}

/* 顺序查找（a[1..n]，a[0] 是哨兵），返回比较次数 */
static int seqSearch(int *a, int n, int key)
{
    int i, cmp = 0;

    a[0] = key;
    for (i = n; a[i] != key; i--) cmp++;
    cmp++;                       /* 命中那一次 */
    return cmp;
}

int main(void)
{
    int a[N + 1], level[N + 1], cntAtLevel[N + 2];
    /* 三种概率分布，都以 1/28 为单位，各自求和恰好 28 */
    int pEq[N]  = {4, 4, 4, 4, 4, 4, 4};
    int pMid[N] = {4, 3, 2, 8, 2, 3, 6};
    int pEnd[N] = {8, 3, 2, 4, 2, 3, 6};
    int i, j, r, sumLevel, h;
    double aslSeq, aslBin;

    a[0] = 0;
    for (i = 1; i <= N; i++) a[i] = 3 * i + 4;   /* 7 10 13 16 19 22 25 */

    printf("有序表 a[1..%d] = ", N);
    for (i = 1; i <= N; i++) printf("%d ", a[i]);
    printf("\n");

    /* ── 判定树：每个元素在第几层被找到 ── */
    printf("\n== 折半查找的判定树 ==\n");
    for (i = 0; i <= N + 1; i++) cntAtLevel[i] = 0;
    h = 0;
    for (i = 1; i <= N; i++) {
        r = binSearch(a + 1, N, a[i]);
        level[i] = r;
        cntAtLevel[r]++;
        if (r > h) h = r;
    }
    printf("  各元素所在的层：");
    for (i = 1; i <= N; i++) printf("a[%d]=%d在第%d层 ", i, a[i], level[i]);
    printf("\n  各层结点个数：");
    for (j = 1; j <= h; j++) printf("第%d层=%d个 ", j, cntAtLevel[j]);
    printf("\n  判定树高度 h = %d，⌈log2(n+1)⌉ = ⌈log2 8⌉ = 3 相符=%d\n", h, h == 3);
    sumLevel = 0;
    for (i = 1; i <= N; i++) sumLevel += level[i];
    printf("  Σ层数 = %d，等概率 ASL_成功 = %d/%d = %.4f\n", sumLevel, sumLevel, N,
           (double)sumLevel / N);

    /* ── 三种概率分布下的 ASL ── */
    printf("\n== 三种概率分布下的 ASL 对照（概率以 1/28 为单位）==\n");
    printf("  分布①等概率      p = ");
    for (i = 0; i < N; i++) printf("%d ", pEq[i]);
    printf("\n  分布②集中在中间  p = ");
    for (i = 0; i < N; i++) printf("%d ", pMid[i]);
    printf("\n  分布③集中在端点  p = ");
    for (i = 0; i < N; i++) printf("%d ", pEnd[i]);
    printf("\n\n");

    {
        int *dists[3];
        const char *names[3];
        int k, numSeq, numBin;

        dists[0] = pEq;  names[0] = "等概率    ";
        dists[1] = pMid; names[1] = "集中中间  ";
        dists[2] = pEnd; names[2] = "集中端点  ";
        for (k = 0; k < 3; k++) {
            int *p = dists[k];

            numSeq = 0;
            numBin = 0;
            for (i = 0; i < N; i++) {
                numSeq += p[i] * (i + 1);            /* 顺序查找：第 i+1 个元素比较 i+1 次 */
                numBin += p[i] * level[i + 1];       /* 折半查找：比较 level 次 */
            }
            aslSeq = (double)numSeq / 28;
            aslBin = (double)numBin / 28;
            printf("  %s：ASL_顺序 = %3d/28 = %.4f   ASL_折半 = %3d/28 = %.4f   折半更优=%d\n",
                   names[k], numSeq, aslSeq, numBin, aslBin, aslBin < aslSeq);
        }
    }

    /* ── 失败 ASL ── */
    printf("\n== 失败时的 ASL ==\n");
    {
        int failKeys[N + 1], totalSeq = 0, totalBin = 0;

        /* n=7 有 8 个失败区间：小于最小、6 个间隙、大于最大 */
        failKeys[0] = 1;
        for (i = 1; i < N; i++) failKeys[i] = a[i] + 1;      /* 落在 a[i] 与 a[i+1] 之间 */
        failKeys[N] = a[N] + 1;
        for (i = 0; i <= N; i++) {
            r = seqSearch(a, N, failKeys[i]);
            totalSeq += r;
            r = binSearch(a + 1, N, failKeys[i]);
            totalBin += -r;
        }
        printf("  8 个失败键：");
        for (i = 0; i <= N; i++) printf("%d ", failKeys[i]);
        printf("\n  顺序查找 ASL_失败 = %d/8 = %.4f（公式 n+1 = %d）\n",
               totalSeq, (double)totalSeq / 8, N + 1);
        printf("  折半查找 ASL_失败 = %d/8 = %.4f\n", totalBin, (double)totalBin / 8);
    }

    printf("\n演示结束\n");
    return 0;
}

#include <stdio.h>

#define N 15

/* ① 从前往后，不带哨兵。keyCmp 与 boundCmp 分别统计两类判断的次数 */
static int seqFront(const int *a, int n, int key, int *keyCmp, int *boundCmp)
{
    int i;

    *keyCmp = 0;
    *boundCmp = 0;
    for (i = 0; i < n; i++) {
        (*boundCmp)++;
        if (a[i] == key) { (*keyCmp)++; return i; }
        (*keyCmp)++;
    }
    return -1;
}

/* ② 从后往前 + 哨兵（a[0] 是哨兵位，数据在 a[1..n]） */
static int seqSentinel(int *a, int n, int key, int *keyCmp)
{
    int i;

    *keyCmp = 0;
    a[0] = key;
    for (i = n; a[i] != key; i--) (*keyCmp)++;
    (*keyCmp)++;
    return i;
}

/* ③ 有序表：a[i] > key 时提前终止失败
   同时统计「关键字比较」与「越界判断」两类次数——教材公式 n/2+1 把终止时的
   那次 i<n 越界判断也算进去，只数关键字比较会少 1/(n+1) */
static int seqSortedEarly(const int *a, int n, int key, int *keyCmp, int *boundCmp, int *early)
{
    int i;

    *keyCmp = 0;
    *boundCmp = 0;
    *early = 0;
    for (i = 0; i < n; i++) {
        (*boundCmp)++;
        (*keyCmp)++;
        if (a[i] == key) return i;
        if (a[i] > key) { *early = 1; return -1; }   /* ★ 提前终止 */
    }
    (*boundCmp)++;                 /* 循环因 i < n 为假而结束，这也是一次判断 */
    return -1;
}

int main(void)
{
    int a[N + 1];
    int i, r, kc, bc, early;
    int totalNoSentinel = 0, totalSentinel = 0;
    int totalSucc = 0, totalFailPlain = 0, totalFailEarly = 0, earlyHit = 0;
    int totalFailEarlyB = 0, plain, ec, eb;
    int failKeys[N + 1];

    a[0] = 0;
    for (i = 1; i <= N; i++) a[i] = 2 * i;          /* 2 4 6 … 30，有序 */

    printf("有序表 a[1..%d] = ", N);
    for (i = 1; i <= N; i++) printf("%d ", a[i]);
    printf("\n");

    /* ── ① 哨兵的操作计数：查遍全部 15 个成功键 ── */
    printf("\n== 哨兵的作用：查遍全部 %d 个成功键 ==\n", N);
    for (i = 1; i <= N; i++) {
        r = seqFront(a + 1, N, a[i], &kc, &bc);
        totalNoSentinel += kc + bc;
        r = seqSentinel(a, N, a[i], &kc);
        totalSentinel += kc;
    }
    printf("  不带哨兵：关键字比较 + 越界判断合计 = %d 次\n", totalNoSentinel);
    printf("  带哨兵  ：只有关键字比较           = %d 次\n", totalSentinel);
    printf("  正好减半 = %d（理论值 n(n+1) = %d 与 n(n+1)/2 = %d）\n",
           totalNoSentinel == 2 * totalSentinel, N * (N + 1), N * (N + 1) / 2);

    /* ASL_成功（只数关键字比较） */
    totalSucc = 0;
    for (i = 1; i <= N; i++) { seqSentinel(a, N, a[i], &kc); totalSucc += kc; }
    printf("  ASL_成功 = %d/%d = %.4f（公式 (n+1)/2 = %.4f）相符=%d\n",
           totalSucc, N, (double)totalSucc / N, (N + 1) / 2.0,
           (double)totalSucc / N == (N + 1) / 2.0);

    /* ── ② 失败 ASL：普通 vs 有序提前终止 ── */
    printf("\n== 失败 ASL：普通顺序查找 vs 有序表提前终止 ==\n");
    failKeys[0] = 1;                                 /* 小于最小 */
    for (i = 1; i < N; i++) failKeys[i] = a[i] + 1;  /* 落在间隙里 */
    failKeys[N] = a[N] + 1;                          /* 大于最大 */
    printf("  %d 个失败键：", N + 1);
    for (i = 0; i <= N; i++) printf("%d ", failKeys[i]);
    printf("\n");

    for (i = 0; i <= N; i++) {
        /* 先把结果存进局部量再 printf：seqSentinel 会改 a[0]，
           把它直接放进 printf 的实参里就会与 kc 的求值顺序打架 */
        r = seqSentinel(a, N, failKeys[i], &kc);
        plain = kc;
        totalFailPlain += plain;

        seqSortedEarly(a + 1, N, failKeys[i], &ec, &eb, &early);
        totalFailEarly += ec;
        totalFailEarlyB += eb;
        if (early) earlyHit++;

        printf("    key=%2d：哨兵版返回 %2d 比较 %2d 次 | 提前终止版 关键字 %2d 次 越界 %2d 次%s\n",
               failKeys[i], r, plain, ec, eb,
               early ? "（a[i] > key 提前退出）" : "（走到表尾）");
    }
    printf("  ASL_失败（哨兵版，只数关键字比较）      = %d/%d = %.4f（公式 n+1 = %d）\n",
           totalFailPlain, N + 1, (double)totalFailPlain / (N + 1), N + 1);
    printf("  ASL_失败（提前终止，只数关键字比较）    = %d/%d = %.4f\n",
           totalFailEarly, N + 1, (double)totalFailEarly / (N + 1));
    printf("  ASL_失败（提前终止，含终止时的越界判断）= %d/%d = %.4f（公式 n/2+1 = %.4f）相符=%d\n",
           totalFailEarlyB, N + 1, (double)totalFailEarlyB / (N + 1), N / 2.0 + 1,
           (double)totalFailEarlyB / (N + 1) == N / 2.0 + 1);
    printf("  提前终止生效的键有 %d 个（只有 key=%d 大于全部元素，必须走到表尾）\n",
           earlyHit, failKeys[N]);

    printf("\n演示结束\n");
    return 0;
}

#include <stdio.h>

#define N 15

/* 正确写法：low <= high，mid = low + (high-low)/2 */
static int binOK(const int *a, int n, int key, int *cmp)
{
    int low = 0, high = n - 1, mid;

    *cmp = 0;
    while (low <= high) {
        mid = low + (high - low) / 2;
        (*cmp)++;
        if (a[mid] == key) return mid;
        if (a[mid] < key) low = mid + 1;
        else high = mid - 1;
    }
    return -1;
}

/* 错误写法一：low < high。★ 注意末尾没有任何补救——
   这正是它「漏查」的原因：low == high 时区间里还剩一个候选元素没比较就退出了 */
static int binBadCond(const int *a, int n, int key, int *cmp)
{
    int low = 0, high = n - 1, mid;

    *cmp = 0;
    while (low < high) {
        mid = low + (high - low) / 2;
        (*cmp)++;
        if (a[mid] == key) return mid;
        if (a[mid] < key) low = mid + 1;
        else high = mid - 1;
    }
    return -1;
}

/* 错误写法二：low = mid（不加 1）→ 死循环，这里加轮数上限来暴露它 */
static int binBadStep(const int *a, int n, int key, int *cmp, int *stuck)
{
    int low = 0, high = n - 1, mid, guard = 0;

    *cmp = 0;
    *stuck = 0;
    while (low <= high) {
        if (++guard > 4 * n) { *stuck = 1; return -1; }   /* 轮数超限 = 区间没缩小 */
        mid = low + (high - low) / 2;
        (*cmp)++;
        if (a[mid] == key) return mid;
        if (a[mid] < key) low = mid;              /* ✗ 少了 +1 */
        else high = mid - 1;
    }
    return -1;
}

int main(void)
{
    int a[N];
    int i, r, cmp, stuck, h = 0, sumSucc = 0, sumFail = 0;
    int cntAtLevel[N + 2], failLevel[N + 2];
    int failKeys[N + 1];
    int lo = 1500000000, hi = 2000000000;
    double sum;

    for (i = 0; i < N; i++) a[i] = 2 * (i + 1);    /* 2 4 6 … 30 */

    printf("有序表 a[0..%d] = ", N - 1);
    for (i = 0; i < N; i++) printf("%d ", a[i]);
    printf("\n");

    /* ── ① 判定树：逐层统计 ── */
    printf("\n== 判定树 ==\n");
    for (i = 0; i <= N + 1; i++) { cntAtLevel[i] = 0; failLevel[i] = 0; }
    for (i = 0; i < N; i++) {
        r = binOK(a, N, a[i], &cmp);
        cntAtLevel[cmp]++;
        sumSucc += cmp;
        if (cmp > h) h = cmp;
        printf("  key=%2d 在下标 %2d 找到，比较 %d 次\n", a[i], r, cmp);
    }
    printf("  各层结点个数：");
    for (i = 1; i <= h; i++) printf("第%d层=%d ", i, cntAtLevel[i]);
    printf("\n  合计 = %d（应等于 n=%d）相符=%d\n",
           cntAtLevel[1] + cntAtLevel[2] + cntAtLevel[3] + cntAtLevel[4] + cntAtLevel[5],
           N,
           cntAtLevel[1] + cntAtLevel[2] + cntAtLevel[3] + cntAtLevel[4] + cntAtLevel[5] == N);
    printf("  树高 h = %d，⌈log2(n+1)⌉ = ⌈log2 16⌉ = 4 相符=%d\n", h, h == 4);
    printf("  ASL_成功 = %d/%d = %.4f（近似公式 log2(n+1)-1 = 3.0000）\n",
           sumSucc, N, (double)sumSucc / N);

    /* ── ② 失败 ASL：n+1 = 16 个失败区间 ── */
    printf("\n== 失败查找：%d 个失败区间 ==\n", N + 1);
    failKeys[0] = 1;
    for (i = 1; i < N; i++) failKeys[i] = a[i - 1] + 1;
    failKeys[N] = a[N - 1] + 1;
    for (i = 0; i <= N; i++) {
        r = binOK(a, N, failKeys[i], &cmp);
        failLevel[cmp]++;
        sumFail += cmp;
        printf("  key=%2d 未找到（返回 %d），比较 %d 次\n", failKeys[i], r, cmp);
    }
    printf("  失败比较次数的分布：");
    for (i = 1; i <= h + 1; i++) if (failLevel[i] > 0) printf("%d次=%d个 ", i, failLevel[i]);
    printf("\n  ASL_失败 = %d/%d = %.4f\n", sumFail, N + 1, (double)sumFail / (N + 1));

    /* ── ③ 两个经典错误写法 ── */
    printf("\n== 错误写法对照 ==\n");
    r = binOK(a, N, a[N - 1], &cmp);
    printf("  查最后一个元素 key=%d：正确写法 → 下标 %d，比较 %d 次\n", a[N - 1], r, cmp);
    r = binBadCond(a, N, a[N - 1], &cmp);
    printf("  查最后一个元素 key=%d：low<high → 下标 %d（-1 表示漏查）比较 %d 次\n",
           a[N - 1], r, cmp);
    r = binBadCond(a, 1, a[0], &cmp);
    printf("  n=1 的表查它唯一的元素：low<high → 下标 %d（明明存在却说找不到）\n", r);

    r = binBadStep(a, N, a[N - 1], &cmp, &stuck);
    printf("  low = mid（少 +1）查 key=%d：卡死=%d 比较次数=%d（轮数超过上限 4n=%d 才被迫退出）\n",
           a[N - 1], stuck, cmp, 4 * N);

    /* ── ④ mid 的溢出防线 ── */
    /* ── ④ mid 的溢出防线 ──
       这里刻意用 double 算出真实的和，而不是真的让 int 溢出：
       有符号整数溢出在 C 里是未定义行为，输出不可复现，不能拿来出题 */
    printf("\n== mid 的两种写法（用 double 算出真实的和，避免真的触发有符号溢出）==\n");
    sum = (double)lo + (double)hi;
    printf("  下标 low=%d high=%d 时：\n", lo, hi);
    printf("    (low+high)/2 需要 low+high = %.0f，超出 int 上限 2147483647 → 溢出成负下标\n", sum);
    printf("    low+(high-low)/2 = %d，始终在 int 范围内 → 正确\n", lo + (hi - lo) / 2);

    printf("\n演示结束\n");
    return 0;
}

#include <stdio.h>

#define N   16
#define MAXS 16           /* 每块的容量上限，留余量给插入演示 */

/* 一块：块内元素 + 实际长度 + 本块最大关键字 */
typedef struct {
    int elem[MAXS];
    int len;
    int maxKey;
} Block;

/* 按块长 s 把有序表 a[0..n-1] 切成若干块 */
static int buildBlocks(const int *a, int n, int s, Block *blk)
{
    int i, j, k = 0;

    for (i = 0; i < n; i += s) {
        blk[k].len = 0;
        blk[k].maxKey = a[i];
        for (j = i; j < n && j < i + s; j++) {
            blk[k].elem[blk[k].len++] = a[j];
            if (a[j] > blk[k].maxKey) blk[k].maxKey = a[j];
        }
        k++;
    }
    return k;                          /* 返回块数 b */
}

/* 索引表是否升序（等价于「块间有序」是否成立） */
static int indexSorted(const Block *blk, int b)
{
    int i;

    for (i = 1; i < b; i++)
        if (blk[i - 1].maxKey >= blk[i].maxKey) return 0;
    return 1;
}

/* 顺序查索引 + 块内顺序查。返回 1=找到，cmpI 与 cmpS 是两步的比较次数 */
static int blockSeq(const Block *blk, int b, int key, int *cmpI, int *cmpS, int *outBlk, int *outPos)
{
    int i, j;

    *cmpI = 0;
    *cmpS = 0;
    for (i = 0; i < b; i++) {
        (*cmpI)++;
        if (key <= blk[i].maxKey) break;      /* 第一个 maxKey >= key 的块 */
    }
    if (i >= b) return 0;                     /* key 大于所有块的最大值 */
    for (j = 0; j < blk[i].len; j++) {
        (*cmpS)++;
        if (blk[i].elem[j] == key) { *outBlk = i; *outPos = j; return 1; }
    }
    return 0;
}

/* 折半查索引（lower_bound：第一个 maxKey >= key 的块）+ 块内顺序查 */
static int blockBin(const Block *blk, int b, int key, int *cmpI, int *cmpS, int *outBlk, int *outPos)
{
    int low = 0, high = b - 1, mid, i, j;

    *cmpI = 0;
    *cmpS = 0;
    while (low <= high) {
        mid = low + (high - low) / 2;
        (*cmpI)++;
        if (key <= blk[mid].maxKey) high = mid - 1;
        else low = mid + 1;
    }
    i = low;
    if (i >= b) return 0;
    for (j = 0; j < blk[i].len; j++) {
        (*cmpS)++;
        if (blk[i].elem[j] == key) { *outBlk = i; *outPos = j; return 1; }
    }
    return 0;
}

/* 折半查找在长度 n 的有序表上的「成功 ASL」：逐个键实测，不用 log 近似公式。
   虚拟表取 a[i] = i，所以只需比较下标，不必真的建表。 */
static double binASL(int n)
{
    long long total = 0;
    int key;

    for (key = 0; key < n; key++) {
        int low = 0, high = n - 1, cnt = 0;

        while (low <= high) {
            int mid = low + (high - low) / 2;

            cnt++;
            if (mid == key) break;
            if (key < mid) high = mid - 1;
            else low = mid + 1;
        }
        total += cnt;
    }
    return (double)total / n;
}

int main(void)
{
    Block blk[N];
    int a[N];
    int i, j, b, s, ci, cs, found, ok, bi, bp;
    int sumI, sumS, bestS, minTotal;
    double theory, measured;

    for (i = 0; i < N; i++) a[i] = 2 * (i + 1);        /* 2 4 … 32，有序 */

    printf("主表 a[0..%d] = ", N - 1);
    for (i = 0; i < N; i++) printf("%d ", a[i]);
    printf("\n");

    /* ── ① 扫描所有分块方案，找最优 s ── */
    printf("\n== 扫描 s = 1..%d，比较「理论公式」与「逐个键实测」==\n", N);
    printf("   s    b    L_I=(b+1)/2  L_S=(s+1)/2  理论ASL   实测ASL   索引升序  16键全找到\n");
    bestS = 0;
    minTotal = 1 << 30;
    for (s = 1; s <= N; s *= 2) {
        b = buildBlocks(a, N, s, blk);
        sumI = 0;
        sumS = 0;
        ok = 1;
        for (i = 0; i < N; i++) {
            found = blockSeq(blk, b, a[i], &ci, &cs, &bi, &bp);
            if (!found) ok = 0;
            sumI += ci;
            sumS += cs;
        }
        theory = (b + 1) / 2.0 + (s + 1) / 2.0;
        measured = (double)(sumI + sumS) / N;
        printf("  %2d   %2d      %.2f         %.2f       %.4f    %.4f      %d         %d\n",
               s, b, (b + 1) / 2.0, (s + 1) / 2.0, theory, measured,
               indexSorted(blk, b), ok);
        if (sumI + sumS < minTotal) { minTotal = sumI + sumS; bestS = s; }
    }
    {
        double sqrtN = 1.0;
        while (sqrtN * sqrtN < N) sqrtN += 1.0;          /* ⌈√n⌉，整数递推不用 math.h */
        printf("  实测最优 s = %d，⌈√n⌉ = %.0f，相符=%d\n", bestS, sqrtN, bestS == (int)sqrtN);
        printf("  最优 ASL = %.4f，⌈√n⌉ + 1 = %.4f，相符=%d\n",
               (double)minTotal / N, sqrtN + 1, (double)minTotal / N == sqrtN + 1);
    }

    /* ── ② s = 4 的细节：索引表、逐块明细、两种查索引方式 ── */
    s = 4;
    b = buildBlocks(a, N, s, blk);
    printf("\n== s = %d（最优分块），b = %d ==\n", s, b);
    printf("  索引表（每块最大关键字）：");
    for (i = 0; i < b; i++) printf("%d ", blk[i].maxKey);
    printf("\n  块间有序（索引表升序）= %d\n", indexSorted(blk, b));
    for (i = 0; i < b; i++) {
        printf("    块%d：", i);
        for (j = 0; j < blk[i].len; j++) printf("%d ", blk[i].elem[j]);
        printf(" maxKey=%d\n", blk[i].maxKey);
    }

    printf("\n  逐键明细（顺序查索引 / 折半查索引）：\n");
    sumI = 0;
    sumS = 0;
    {
        int sumIB = 0, ci2, cs2, blk2, pos2;

        for (i = 0; i < N; i++) {
            found = blockSeq(blk, b, a[i], &ci, &cs, &blk2, &pos2);
            blockBin(blk, b, a[i], &ci2, &cs2, &blk2, &pos2);
            sumI += ci;
            sumS += cs;
            sumIB += ci2;
            printf("    key=%2d 在第%d块第%d位：索引%d次+块内%d次=%d次 | 折半查索引%d次+块内%d次=%d次\n",
                   a[i], blk2, pos2, ci, cs, ci + cs, ci2, cs2, ci2 + cs2);
        }
        printf("  顺序查索引：ASL = (%d+%d)/%d = %.4f\n", sumI, sumS, N, (double)(sumI + sumS) / N);
        printf("  折半查索引：ASL = (%d+%d)/%d = %.4f\n", sumIB, sumS, N, (double)(sumIB + sumS) / N);
    }

    /* ── ③ 三种方法的量级对比 ── */
    printf("\n== 三种查找方法的 ASL 量级对比（折半那一列是逐个键实测，不是近似公式）==\n");
    {
        int sizes[3];
        sizes[0] = N;
        sizes[1] = 10000;
        sizes[2] = 1000000;
        for (i = 0; i < 3; i++) {
            int n = sizes[i];
            double sq = 1.0;
            while (sq * sq < n) sq += 1.0;            /* ⌈√n⌉，整数递推不用 math.h */
            printf("  n=%d：顺序=%.1f  分块(最优)=⌈√n⌉+1=%.1f  折半(实测)=%.4f\n",
                   n, (n + 1) / 2.0, sq + 1, binASL(n));
        }
    }

    /* ── ④ 插入代价：有序表 vs 分块结构 ── */
    printf("\n== 插入 key=13 的代价对比 ==\n");
    {
        int shift = 0, pos = -1, oldMax;

        for (i = 0; i < N; i++) if (a[i] > 13) { pos = i; break; }
        shift = N - pos;                              /* a[pos..N-1] 全部右移一格 */
        printf("  折半查找用的有序表：13 要插在下标 %d，需右移 %d 个元素（平均 n/2 = %d）\n",
               pos, shift, N / 2);

        /* 分块结构：先找块，再追加到块尾 */
        for (i = 0; i < b; i++) if (13 <= blk[i].maxKey) break;
        if (i < b) {
            oldMax = blk[i].maxKey;
            printf("  分块结构：13 <= blk[%d].maxKey=%d，落在第 %d 块\n", i, blk[i].maxKey, i);
            printf("    该块插入前 = ");
            for (j = 0; j < blk[i].len; j++) printf("%d ", blk[i].elem[j]);
            blk[i].elem[blk[i].len++] = 13;           /* ★ 块内无序，直接追加 */
            if (13 > oldMax) blk[i].maxKey = 13;
            printf("\n    追加 13 后 = ");
            for (j = 0; j < blk[i].len; j++) printf("%d ", blk[i].elem[j]);
            printf("\n    移动元素个数 = 0，索引表是否需要更新（13 > 原maxKey=%d）= %d\n",
                   oldMax, 13 > oldMax);
            printf("    索引表仍然升序 = %d\n", indexSorted(blk, b));
        }
    }

    printf("\n演示结束\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAXN 32

typedef struct BSTNode {
    int key;
    struct BSTNode *l, *r;
} BSTNode, *BSTree;

static BSTNode *newNode(int key)
{
    BSTree p = (BSTree)malloc(sizeof(BSTNode));

    if (p == NULL) { printf("内存分配失败\n"); exit(1); }
    p->key = key;
    p->l = NULL;
    p->r = NULL;
    return p;
}

static void destroyBST(BSTree t)
{
    if (t == NULL) return;
    destroyBST(t->l);
    destroyBST(t->r);
    free(t);
}

static void bstInsert(BSTree *t, int key)
{
    if (*t == NULL) { *t = newNode(key); return; }
    if (key < (*t)->key) bstInsert(&(*t)->l, key);
    else if (key > (*t)->key) bstInsert(&(*t)->r, key);
    /* key 相等则忽略：BST 不允许重复关键字 */
}

static BSTree buildFrom(const int *keys, int n)
{
    BSTree t = NULL;
    int i;

    for (i = 0; i < n; i++) bstInsert(&t, keys[i]);
    return t;
}

/* 括号表示法：45(24(12(-,15),37(30,-)),53(-,93(61,-))) */
static void printShape(BSTree t)
{
    if (t == NULL) { printf("-"); return; }
    printf("%d", t->key);
    if (t->l == NULL && t->r == NULL) return;
    printf("(");
    printShape(t->l);
    printf(",");
    printShape(t->r);
    printf(")");
}

static int height(BSTree t)
{
    int hl, hr;

    if (t == NULL) return 0;
    hl = height(t->l);
    hr = height(t->r);
    return 1 + (hl > hr ? hl : hr);
}

static void inorder(BSTree t, int *out, int *len)
{
    if (t == NULL) return;
    inorder(t->l, out, len);
    out[(*len)++] = t->key;
    inorder(t->r, out, len);
}

/* 该关键字在树中的层数（根在第 1 层）；不存在返回 0 */
static int levelOf(BSTree t, int key, int d)
{
    if (t == NULL) return 0;
    if (t->key == key) return d;
    if (key < t->key) return levelOf(t->l, key, d + 1);
    return levelOf(t->r, key, d + 1);
}

/* 结构是否完全相同（只比形态与关键字） */
static int sameTree(BSTree a, BSTree b)
{
    if (a == NULL && b == NULL) return 1;
    if (a == NULL || b == NULL) return 0;
    if (a->key != b->key) return 0;
    return sameTree(a->l, b->l) && sameTree(a->r, b->r);
}

/* 对有序数组做折半，按「判定树的先序」输出关键字 */
static void decisionPreOrder(const int *a, int low, int high, int *out, int *len)
{
    int mid;

    if (low > high) return;
    mid = low + (high - low) / 2;
    out[(*len)++] = a[mid];
    decisionPreOrder(a, low, mid - 1, out, len);
    decisionPreOrder(a, mid + 1, high, out, len);
}

static void printSeq(const int *v, int len)
{
    int i;

    if (len == 0) { printf("(空)"); return; }
    for (i = 0; i < len; i++) { if (i > 0) printf(" "); printf("%d", v[i]); }
}

int main(void)
{
    /* 四种插入次序，元素集合都是 {12,24,37,45,53,93} */
    int ord[4][6] = {
        {45, 24, 53, 12, 37, 93},        /* 教材常用例 */
        {12, 24, 37, 45, 53, 93},        /* 升序 → 右单支 */
        {93, 53, 45, 37, 24, 12},        /* 降序 → 左单支 */
        {24, 12, 45, 37, 53, 93}         /* 根偏小，右子树较深 */
    };
    const char *desc[4] = {
        "教材例 45,24,53,12,37,93",
        "升序 12,24,37,45,53,93",
        "降序 93,53,45,37,24,12",
        "偏斜 24,12,45,37,53,93"
    };
    int sorted[6] = {12, 24, 37, 45, 53, 93};
    BSTree trees[4], decTree;
    int seq[4][MAXN], len[4], decSeq[MAXN], decLen = 0;
    int decOrder[MAXN], decOrderLen = 0;
    int i, k, sumLevel, allSame = 1;

    printf("元素集合 = ");
    printSeq(sorted, 6);
    printf("（n = 6）\n");

    /* ── ① 四种插入次序 ── */
    printf("\n== 四种插入次序的形态、高度与 ASL ==\n");
    for (k = 0; k < 4; k++) {
        trees[k] = buildFrom(ord[k], 6);
        len[k] = 0;
        inorder(trees[k], seq[k], &len[k]);
        sumLevel = 0;
        for (i = 0; i < 6; i++) sumLevel += levelOf(trees[k], sorted[i], 1);
        printf("  树%d：%s\n", k + 1, desc[k]);
        printf("      形态 = ");
        printShape(trees[k]);
        printf("\n      高度 h = %d   中序 = ", height(trees[k]));
        printSeq(seq[k], len[k]);
        printf("\n      Σ层数 = %d   ASL_成功 = %d/6 = %.4f\n",
               sumLevel, sumLevel, sumLevel / 6.0);
        printf("      各元素层数：");
        for (i = 0; i < 6; i++) printf("%d→%d ", sorted[i], levelOf(trees[k], sorted[i], 1));
        printf("\n");
        if (k > 0 && !sameTree(trees[k], trees[0])) allSame = 0;
    }
    {
        int same = 1;

        for (k = 1; k < 4; k++) {
            if (len[k] != len[0]) { same = 0; break; }
            for (i = 0; i < len[0]; i++) if (seq[k][i] != seq[0][i]) { same = 0; break; }
        }
        printf("  四棵树的中序序列完全相同 = %d，形态两两相同 = %d\n", same, allSame);
    }
    printf("  理想平衡高度 ⌈log2(n+1)⌉ = ⌈log2 7⌉ = 3，最坏 = n = 6\n");

    /* ── ② 判定树同构验证 ── */
    printf("\n== 折半查找判定树 与 BST 的同构关系 ==\n");
    decisionPreOrder(sorted, 0, 5, decOrder, &decOrderLen);
    printf("  有序数组 = ");
    printSeq(sorted, 6);
    printf("\n  判定树的先序 = ");
    printSeq(decOrder, decOrderLen);
    decTree = buildFrom(decOrder, decOrderLen);
    printf("\n  按该先序插入得到的 BST 形态 = ");
    printShape(decTree);
    decLen = 0;
    inorder(decTree, decSeq, &decLen);
    printf("\n  其中序 = ");
    printSeq(decSeq, decLen);
    printf("\n  高度 = %d（与教材例①的树高度相同？%d）\n",
           height(decTree), height(decTree) == height(trees[0]));
    printf("  与教材例①的树同构 = %d（形态不同）\n", sameTree(decTree, trees[0]));
    {
        int sumDec = 0, sumFirst = 0;

        for (i = 0; i < 6; i++) {
            sumDec += levelOf(decTree, sorted[i], 1);
            sumFirst += levelOf(trees[0], sorted[i], 1);
        }
        printf("  判定树的 Σ层数 = %d，ASL_成功 = %d/6 = %.4f\n", sumDec, sumDec, sumDec / 6.0);
        printf("  教材例①的 Σ层数 = %d，ASL_成功 = %d/6 = %.4f → 两者 ASL 相同？%d\n",
               sumFirst, sumFirst, sumFirst / 6.0, sumDec == sumFirst);
    }

    /* 直接按「折半查找的过程」建判定树，作为标准答案 */
    printf("\n  标准判定树（递归取 mid 建成）：\n");
    {
        /* 用同一套插入函数，但按层序插入 —— 层序同样保证父先于子 */
        int lvlOrder[MAXN], lvlLen = 0;
        int low = 0, high = 5;
        int q[64][2], front = 0, rear = 0, mid2;

        q[rear][0] = low;
        q[rear++][1] = high;
        while (front < rear) {
            low = q[front][0];
            high = q[front++][1];
            if (low > high) continue;
            mid2 = low + (high - low) / 2;
            lvlOrder[lvlLen++] = sorted[mid2];
            q[rear][0] = low; q[rear++][1] = mid2 - 1;
            q[rear][0] = mid2 + 1; q[rear++][1] = high;
        }
        printf("    判定树的层序 = ");
        printSeq(lvlOrder, lvlLen);
        {
            BSTree lvlTree = buildFrom(lvlOrder, lvlLen);
            printf("\n    按层序插入得到的 BST = ");
            printShape(lvlTree);
            printf("\n    与按先序插入的结果同构 = %d\n", sameTree(lvlTree, decTree));
            destroyBST(lvlTree);
        }
    }

    /* ── ③ 形态数：Catalan ── */
    printf("\n== n 个不同关键字的 BST 形态数（Catalan 数）==\n");
    {
        int h[9];
        int n2, ii;

        h[0] = 1;
        for (n2 = 1; n2 <= 8; n2++) {
            h[n2] = 0;
            for (ii = 0; ii < n2; ii++) h[n2] += h[ii] * h[n2 - 1 - ii];
        }
        printf("  h(0..8) = ");
        for (n2 = 0; n2 <= 8; n2++) printf("%d ", h[n2]);
        printf("\n  h(6) = %d 种形态，本例演示了其中 5 种\n", h[6]);
        printf("  排列数 6! = 720 远大于 132 —— 不同排列会给出同一棵树\n");
    }

    for (k = 0; k < 4; k++) destroyBST(trees[k]);
    destroyBST(decTree);
    printf("\n五棵树已释放\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAXN 32

typedef struct BSTNode {
    int key;
    struct BSTNode *l, *r;
} BSTNode, *BSTree;

static BSTNode *newNode(int key)
{
    BSTree p = (BSTree)malloc(sizeof(BSTNode));

    if (p == NULL) { printf("内存分配失败\n"); exit(1); }
    p->key = key;
    p->l = NULL;
    p->r = NULL;
    return p;
}

static void destroyBST(BSTree t)
{
    if (t == NULL) return;
    destroyBST(t->l);
    destroyBST(t->r);
    free(t);
}

static void bstInsert(BSTree *t, int key)
{
    if (*t == NULL) { *t = newNode(key); return; }
    if (key < (*t)->key) bstInsert(&(*t)->l, key);
    else if (key > (*t)->key) bstInsert(&(*t)->r, key);
}

static BSTree buildFrom(const int *keys, int n)
{
    BSTree t = NULL;
    int i;

    for (i = 0; i < n; i++) bstInsert(&t, keys[i]);
    return t;
}

/* 用直接前驱替代。返回 0=未找到 1=叶子 2=单孩子 3=双孩子 */
static int bstDeletePred(BSTree *t, int key)
{
    BSTree q, *slot;
    int child;

    if (*t == NULL) return 0;
    if (key < (*t)->key) return bstDeletePred(&(*t)->l, key);
    if (key > (*t)->key) return bstDeletePred(&(*t)->r, key);

    if ((*t)->l != NULL && (*t)->r != NULL) {        /* 情形③ */
        slot = &(*t)->l;                             /* slot 始终指向「q 所在的指针槽」 */
        q = *slot;
        while (q->r != NULL) { slot = &q->r; q = q->r; }
        (*t)->key = q->key;                          /* 用前驱的关键字覆盖 */
        *slot = q->l;                                /* 前驱必无右孩子，只可能有左孩子 */
        free(q);
        return 3;
    }
    q = *t;                                          /* 情形①② */
    *t = (q->l != NULL) ? q->l : q->r;
    child = (*t == NULL);
    free(q);
    return child ? 1 : 2;
}

/* 用直接后继替代（镜像写法） */
static int bstDeleteSucc(BSTree *t, int key)
{
    BSTree q, *slot;
    int child;

    if (*t == NULL) return 0;
    if (key < (*t)->key) return bstDeleteSucc(&(*t)->l, key);
    if (key > (*t)->key) return bstDeleteSucc(&(*t)->r, key);

    if ((*t)->l != NULL && (*t)->r != NULL) {
        slot = &(*t)->r;
        q = *slot;
        while (q->l != NULL) { slot = &q->l; q = q->l; }
        (*t)->key = q->key;
        *slot = q->r;                                /* 后继必无左孩子，只可能有右孩子 */
        free(q);
        return 3;
    }
    q = *t;
    *t = (q->l != NULL) ? q->l : q->r;
    child = (*t == NULL);
    free(q);
    return child ? 1 : 2;
}

static void printShape(BSTree t)
{
    if (t == NULL) { printf("(空树)"); return; }
    printf("%d", t->key);
    if (t->l == NULL && t->r == NULL) return;
    printf("(");
    if (t->l == NULL) printf("-"); else printShape(t->l);
    printf(",");
    if (t->r == NULL) printf("-"); else printShape(t->r);
    printf(")");
}

static int height(BSTree t)
{
    int hl, hr;

    if (t == NULL) return 0;
    hl = height(t->l);
    hr = height(t->r);
    return 1 + (hl > hr ? hl : hr);
}

static void inorder(BSTree t, int *out, int *len)
{
    if (t == NULL) return;
    inorder(t->l, out, len);
    out[(*len)++] = t->key;
    inorder(t->r, out, len);
}

/* 中序是否严格升序（等价于「是不是合法 BST」） */
static int isBSTValid(const int *v, int len)
{
    int i;

    for (i = 1; i < len; i++) if (v[i - 1] >= v[i]) return 0;
    return 1;
}

/* 中序是否恰好等于「orig 去掉 removed」 */
static int matchesRemoval(const int *orig, int origLen, const int *now, int nowLen, int removed)
{
    int i, j = 0;

    if (nowLen != origLen - 1) return 0;
    for (i = 0; i < origLen; i++) {
        if (orig[i] == removed) continue;
        if (now[j] != orig[i]) return 0;
        j++;
    }
    return j == nowLen;
}

static void printSeq(const int *v, int len)
{
    int i;

    if (len == 0) { printf("(空)"); return; }
    for (i = 0; i < len; i++) { if (i > 0) printf(" "); printf("%d", v[i]); }
}

/* 打印一次删除的完整报告 */
static void report(const char *tag, BSTree t, int caze,
                   const int *orig, int origLen, int removed)
{
    int now[MAXN], nowLen = 0;

    inorder(t, now, &nowLen);
    printf("  %s 返回情形=%d\n", tag, caze);
    printf("      形态 = ");
    printShape(t);
    printf("\n      高度 = %d   结点数 = %d\n", height(t), nowLen);
    printf("      中序 = ");
    printSeq(now, nowLen);
    printf("\n      仍是合法 BST（中序严格升序）= %d\n", isBSTValid(now, nowLen));
    if (removed >= 0)
        printf("      中序 == 原序列去掉 %d = %d\n", removed,
               matchesRemoval(orig, origLen, now, nowLen, removed));
}

int main(void)
{
    int keys[9] = {45, 24, 53, 12, 37, 93, 15, 30, 61};
    int orig[MAXN], origLen = 0;
    BSTree t;
    int i, caze;

    t = buildFrom(keys, 9);
    inorder(t, orig, &origLen);
    printf("原始树：按 %d 个关键字依次插入\n  插入次序 = ", 9);
    printSeq(keys, 9);
    printf("\n  形态 = ");
    printShape(t);
    printf("\n  高度 = %d   中序 = ", height(t));
    printSeq(orig, origLen);
    printf("\n  中序严格升序 = %d\n", isBSTValid(orig, origLen));
    {
        int lv[9], sum = 0;
        int keysSorted[9] = {12, 15, 24, 30, 37, 45, 53, 61, 93};
        /* 层数：根在第 1 层 */
        for (i = 0; i < 9; i++) {
            BSTree p = t;
            lv[i] = 1;
            while (p != NULL && p->key != keysSorted[i]) {
                p = (keysSorted[i] < p->key) ? p->l : p->r;
                lv[i]++;
            }
            sum += lv[i];
        }
        printf("  各元素层数：");
        for (i = 0; i < 9; i++) printf("%d→%d ", keysSorted[i], lv[i]);
        printf("\n  ASL_成功 = %d/9 = %.4f\n", sum, sum / 9.0);
    }
    destroyBST(t);

    /* ── 情形①：删叶子 ── */
    printf("\n== 情形① 删叶子（唯一的孩子是 NULL）==\n");
    t = buildFrom(keys, 9);
    caze = bstDeletePred(&t, 15);
    report("删 15（12 的右孩子）", t, caze, orig, origLen, 15);
    destroyBST(t);

    t = buildFrom(keys, 9);
    caze = bstDeletePred(&t, 30);
    report("删 30（37 的左孩子）", t, caze, orig, origLen, 30);
    destroyBST(t);

    /* ── 情形②：删单孩子结点 ── */
    printf("\n== 情形② 只有一个孩子：让孩子顶替自己的位置 ==\n");
    t = buildFrom(keys, 9);
    caze = bstDeletePred(&t, 12);
    report("删 12（只有右孩子 15）", t, caze, orig, origLen, 12);
    destroyBST(t);

    t = buildFrom(keys, 9);
    caze = bstDeletePred(&t, 93);
    report("删 93（只有左孩子 61）", t, caze, orig, origLen, 93);
    destroyBST(t);

    t = buildFrom(keys, 9);
    caze = bstDeletePred(&t, 53);
    report("删 53（只有右孩子 93）", t, caze, orig, origLen, 53);
    destroyBST(t);

    t = buildFrom(keys, 9);
    caze = bstDeletePred(&t, 37);
    report("删 37（只有左孩子 30）", t, caze, orig, origLen, 37);
    destroyBST(t);

    /* ── 情形③：删双孩子结点，前驱法 vs 后继法 ── */
    printf("\n== 情形③ 左右子树都有：前驱法 与 后继法 对照 ==\n");
    printf("  删根 45。直接前驱 = 左子树最大者 = 从 24 一路往右 → 37（37 只有左孩子 30）\n");
    printf("            直接后继 = 右子树最小者 = 从 53 一路往左 → 53 自己（53 没有左孩子）\n");
    t = buildFrom(keys, 9);
    caze = bstDeletePred(&t, 45);
    report("前驱法删 45", t, caze, orig, origLen, 45);
    {
        BSTree t2 = buildFrom(keys, 9);
        int c2 = bstDeleteSucc(&t2, 45);
        int nowP[MAXN], nowS[MAXN], lp = 0, ls = 0, same = 1;

        report("后继法删 45", t2, c2, orig, origLen, 45);
        inorder(t, nowP, &lp);
        inorder(t2, nowS, &ls);
        if (lp != ls) same = 0;
        else for (i = 0; i < lp; i++) if (nowP[i] != nowS[i]) { same = 0; break; }
        printf("\n  ★ 两种方法的中序序列完全相同 = %d\n", same);
        printf("  ★ 两种方法的树形态相同 = %d（删除结果本来就不唯一）\n",
               height(t) == height(t2) && same && nowP[0] == nowS[0] && t->key == t2->key);
        destroyBST(t2);
    }
    destroyBST(t);

    /* ── 未找到 ── */
    printf("\n== 删除不存在的关键字 ==\n");
    t = buildFrom(keys, 9);
    caze = bstDeletePred(&t, 100);
    report("删 100（不在树中）", t, caze, orig, origLen, -1);
    destroyBST(t);

    /* ── 连续删空 ── */
    printf("\n== 依次删除全部 9 个结点 ==\n");
    t = buildFrom(keys, 9);
    for (i = 0; i < 9; i++) {
        int now[MAXN], nowLen = 0;

        caze = bstDeletePred(&t, keys[i]);
        inorder(t, now, &nowLen);
        printf("  删 %2d（情形%d）后剩 %d 个：", keys[i], caze, nowLen);
        printSeq(now, nowLen);
        printf("   合法BST=%d\n", isBSTValid(now, nowLen));
    }
    printf("  最终树为空 = %d\n", t == NULL);
    destroyBST(t);

    printf("\n演示结束\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAXBUF 256

typedef struct AVLNode {
    int key;
    int bf;                      /* 平衡因子 = 左子树高度 - 右子树高度 */
    struct AVLNode *l, *r;
} AVLNode, *AVLTree;

static AVLNode *mk(int key, AVLTree l, AVLTree r)
{
    AVLNode *p = (AVLNode *)malloc(sizeof(AVLNode));
    p->key = key;
    p->bf  = 0;
    p->l   = l;
    p->r   = r;
    return p;
}

static int heightOf(AVLTree t)
{
    int hl, hr;
    if (t == NULL) return 0;
    hl = heightOf(t->l);
    hr = heightOf(t->r);
    return 1 + (hl > hr ? hl : hr);
}

/* 用真实高度重算每个结点的 bf，返回高度。用来把树恢复到「bf 字段与结构一致」的状态 */
static int recalcBF(AVLTree t)
{
    int hl, hr;
    if (t == NULL) return 0;
    hl = recalcBF(t->l);
    hr = recalcBF(t->r);
    t->bf = hl - hr;
    return 1 + (hl > hr ? hl : hr);
}

/* 数出「存着的 bf」与「按真实高度算出的 bf」不一致的结点个数。
   必须在 recalcBF 之前调用，否则永远数出 0，等于没有检验。 */
static int countBFMismatch(AVLTree t)
{
    int hl, hr, bad;
    if (t == NULL) return 0;
    bad = countBFMismatch(t->l) + countBFMismatch(t->r);
    hl = heightOf(t->l);
    hr = heightOf(t->r);
    if (t->bf != hl - hr) bad++;
    return bad;
}

/* 返回 1 = 全树 |bf| <= 1；bad 记录第一个违例结点的关键字 */
static int checkBal(AVLTree t, int *bad)
{
    if (t == NULL) return 1;
    if (t->bf < -1 || t->bf > 1) { *bad = t->key; return 0; }
    if (!checkBal(t->l, bad)) return 0;
    return checkBal(t->r, bad);
}

static void inorder(AVLTree t, int *out, int *len)
{
    if (t == NULL) return;
    inorder(t->l, out, len);
    out[(*len)++] = t->key;
    inorder(t->r, out, len);
}

/* 括号表示法：叶子不打括号，空孩子打 '-' */
static void printShape(AVLTree t, char *buf, int *len)
{
    int n;
    if (t == NULL) { buf[(*len)++] = '-'; return; }
    n = sprintf(buf + *len, "%d", t->key);
    *len += n;
    if (t->l == NULL && t->r == NULL) return;
    buf[(*len)++] = '(';
    printShape(t->l, buf, len);
    buf[(*len)++] = ',';
    printShape(t->r, buf, len);
    buf[(*len)++] = ')';
}

static void shape(AVLTree t, char *buf)
{
    int len = 0;
    printShape(t, buf, &len);
    buf[len] = '\0';
}

static void seqToStr(const int *v, int len, char *buf)
{
    int i, n = 0;
    if (len == 0) { sprintf(buf, "(空)"); return; }
    for (i = 0; i < len; i++) {
        if (i > 0) buf[n++] = ' ';
        n += sprintf(buf + n, "%d", v[i]);
    }
    buf[n] = '\0';
}

static int isAsc(const int *v, int len)
{
    int i;
    for (i = 1; i < len; i++) if (v[i - 1] >= v[i]) return 0;
    return 1;
}

static int seqEqual(const int *a, int la, const int *b, int lb)
{
    int i;
    if (la != lb) return 0;
    for (i = 0; i < la; i++) if (a[i] != b[i]) return 0;
    return 1;
}

/* 右单旋：B = A->l，B 成为新根，B 的右子树变成 A 的左子树 */
static void rightRotate(AVLTree *a)
{
    AVLTree b = (*a)->l;
    (*a)->l = b->r;
    b->r = *a;
    *a = b;
}

/* 左单旋：B = A->r，B 成为新根，B 的左子树变成 A 的右子树 */
static void leftRotate(AVLTree *a)
{
    AVLTree b = (*a)->r;
    (*a)->r = b->l;
    b->l = *a;
    *a = b;
}

/* 只按 BST 规则插入，不做任何平衡调整——用来构造「失衡现场」 */
static int bstInsert(AVLTree *t, int key)
{
    if (*t == NULL) { *t = mk(key, NULL, NULL); return 1; }
    if (key == (*t)->key) return 0;
    if (key < (*t)->key) return bstInsert(&(*t)->l, key);
    return bstInsert(&(*t)->r, key);
}

static void destroy(AVLTree t)
{
    if (t == NULL) return;
    destroy(t->l);
    destroy(t->r);
    free(t);
}

/* 一个案例：before 是一棵合法 AVL 树，插入 insKey 之后根结点失衡，做一次调整。
   四条断言全部由代码算出来，不是写在字符串里的结论：
   ① 旋转后高度 == 插入前高度   ② 旋转前后中序序列逐字相同
   ③ 全树 |bf| <= 1             ④ 存着的 bf 与按真实高度算出的 bf 完全一致 */
static void demo(const char *label, AVLTree before, int insKey)
{
    AVLTree root = before;
    char s1[MAXBUF], s2[MAXBUF], s3[MAXBUF], q1[MAXBUF], q2[MAXBUF], cBuf[48];
    int in1[16], in2[16], l1 = 0, l2 = 0;
    int h0, h1, h2, rootBf, childBf, c = 0, type, bad = -1, bal, mism, same;
    const char *rotName[] = { "无", "LL→右单旋", "RR→左单旋",
                              "LR→先左旋孩子再右旋根", "RL→先右旋孩子再左旋根" };

    recalcBF(root);
    h0 = heightOf(root);
    shape(root, s1);

    bstInsert(&root, insKey);
    recalcBF(root);
    h1 = heightOf(root);
    shape(root, s2);
    inorder(root, in1, &l1);
    seqToStr(in1, l1, q1);

    rootBf  = root->bf;
    childBf = (rootBf == 2) ? root->l->bf : root->r->bf;

    /* 判定类型：A 的 bf 决定左重还是右重，B 的 bf 决定单旋还是双旋 */
    if (rootBf == 2) {
        type = (childBf == 1) ? 1 : 3;
        c = (type == 3) ? root->l->r->bf : 0;      /* ★ 必须在旋转之前读 */
    } else {
        type = (childBf == -1) ? 2 : 4;
        c = (type == 4) ? root->r->l->bf : 0;
    }

    switch (type) {
    case 1:                                        /* LL → 右单旋，两者 bf 归零 */
        rightRotate(&root);
        root->bf = 0;
        root->r->bf = 0;
        break;
    case 2:                                        /* RR → 左单旋，两者 bf 归零 */
        leftRotate(&root);
        root->bf = 0;
        root->l->bf = 0;
        break;
    case 3:                                        /* LR → 先左旋孩子，再右旋根 */
        leftRotate(&root->l);
        rightRotate(&root);
        root->bf = 0;
        if (c == 1)       { root->l->bf = 0; root->r->bf = -1; }
        else if (c == -1) { root->l->bf = 1; root->r->bf = 0;  }
        else              { root->l->bf = 0; root->r->bf = 0;  }
        break;
    default:                                       /* RL → 先右旋孩子，再左旋根 */
        rightRotate(&root->r);
        leftRotate(&root);
        root->bf = 0;
        if (c == 1)       { root->l->bf = 0; root->r->bf = -1; }
        else if (c == -1) { root->l->bf = 1; root->r->bf = 0;  }
        else              { root->l->bf = 0; root->r->bf = 0;  }
        break;
    }

    mism = countBFMismatch(root);                  /* 必须在 recalcBF 之前数 */
    bad = -1;
    bal = checkBal(root, &bad);
    h2 = heightOf(root);
    shape(root, s3);
    inorder(root, in2, &l2);
    seqToStr(in2, l2, q2);
    same = seqEqual(in1, l1, in2, l2);

    /* 单旋没有 C 这个结点，所以只在双旋时打印 c */
    if (type == 3 || type == 4) sprintf(cBuf, "，C 旋转前的 bf = %d", c);
    else                        sprintf(cBuf, "%s", "");

    printf("  [%s] 判定为 %s%s\n", label, rotName[type], cBuf);
    printf("    插入前     %s（高度 %d）\n", s1, h0);
    printf("    插入 %2d 后 %s（高度 %d；根 bf = %+d，失衡侧孩子 bf = %+d）\n",
           insKey, s2, h1, rootBf, childBf);
    printf("    旋转后     %s（高度 %d）\n", s3, h2);
    printf("    高度复原？%d  中序不变？%d  全树|bf|<=1？%d  bf 与实算高度不符的结点数 %d\n",
           h2 == h0, same, bal, mism);
    printf("    中序 %s → %s，严格升序？%d\n", q1, q2, isAsc(in2, l2));

    destroy(root);
}

int main(void)
{
    printf("== 四类旋转的最小实例（每个案例的插入前都是一棵合法 AVL 树）==\n");
    demo("LL", mk(50, mk(30, mk(20, NULL, NULL), mk(40, NULL, NULL)),
                     mk(70, NULL, NULL)), 10);
    demo("RR", mk(50, mk(30, NULL, NULL),
                     mk(70, mk(60, NULL, NULL), mk(80, NULL, NULL))), 90);
    demo("LR", mk(50, mk(30, mk(20, NULL, NULL), mk(40, NULL, NULL)),
                     mk(70, NULL, NULL)), 45);
    demo("RL", mk(50, mk(30, NULL, NULL),
                     mk(70, mk(60, NULL, NULL), mk(80, NULL, NULL))), 55);

    printf("\n== LR 的三种子情形：C 旋转前的 bf 决定 A 与 B 旋转后的 bf ==\n");
    demo("LR c=+1", mk(40, mk(20, mk(10, NULL, NULL), mk(30, NULL, NULL)),
                          mk(50, NULL, NULL)), 25);
    demo("LR c=-1", mk(40, mk(20, mk(10, NULL, NULL), mk(30, NULL, NULL)),
                          mk(50, NULL, NULL)), 35);
    demo("LR c=0 ", mk(30, mk(20, NULL, NULL), NULL), 25);

    printf("\n== RL 的三种子情形：把 LR 那张表的 A 与 B 对调就是它 ==\n");
    demo("RL c=+1", mk(40, mk(10, NULL, NULL),
                          mk(50, mk(45, NULL, NULL), mk(60, NULL, NULL))), 42);
    demo("RL c=-1", mk(40, mk(10, NULL, NULL),
                          mk(50, mk(45, NULL, NULL), mk(60, NULL, NULL))), 48);
    demo("RL c=0 ", mk(30, NULL, mk(40, NULL, NULL)), 35);

    printf("\n十个案例全部释放完毕\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAXBUF 512

typedef struct AVLNode {
    int key;
    int bf;                      /* 平衡因子 = 左子树高度 - 右子树高度 */
    struct AVLNode *l, *r;
} AVLNode, *AVLTree;

/* 本次插入的统计：旋转类型、失衡点关键字、回溯更新了几个祖先、是否出现过「bf 变 0 提前停止」 */
static int g_rot, g_zKey, g_upd, g_stop;

static AVLNode *mk(int key, AVLTree l, AVLTree r)
{
    AVLNode *p = (AVLNode *)malloc(sizeof(AVLNode));
    p->key = key;
    p->bf  = 0;
    p->l   = l;
    p->r   = r;
    return p;
}

static int heightOf(AVLTree t)
{
    int hl, hr;
    if (t == NULL) return 0;
    hl = heightOf(t->l);
    hr = heightOf(t->r);
    return 1 + (hl > hr ? hl : hr);
}

/* 数出「存着的 bf」与「按真实高度算出的 bf」不一致的结点个数。
   avlInsert 是增量维护 bf 的，这个函数就是用来验证它维护得对不对——
   必须在任何重算之前调用，否则永远数出 0，等于没有检验。 */
static int countBFMismatch(AVLTree t)
{
    int hl, hr, bad;
    if (t == NULL) return 0;
    bad = countBFMismatch(t->l) + countBFMismatch(t->r);
    hl = heightOf(t->l);
    hr = heightOf(t->r);
    if (t->bf != hl - hr) bad++;
    return bad;
}

static int checkBal(AVLTree t, int *bad)
{
    if (t == NULL) return 1;
    if (t->bf < -1 || t->bf > 1) { *bad = t->key; return 0; }
    if (!checkBal(t->l, bad)) return 0;
    return checkBal(t->r, bad);
}

static void inorder(AVLTree t, int *out, int *len)
{
    if (t == NULL) return;
    inorder(t->l, out, len);
    out[(*len)++] = t->key;
    inorder(t->r, out, len);
}

static void printShape(AVLTree t, char *buf, int *len)
{
    int n;
    if (t == NULL) { buf[(*len)++] = '-'; return; }
    n = sprintf(buf + *len, "%d", t->key);
    *len += n;
    if (t->l == NULL && t->r == NULL) return;
    buf[(*len)++] = '(';
    printShape(t->l, buf, len);
    buf[(*len)++] = ',';
    printShape(t->r, buf, len);
    buf[(*len)++] = ')';
}

static void shape(AVLTree t, char *buf)
{
    int len = 0;
    printShape(t, buf, &len);
    buf[len] = '\0';
}

static void seqToStr(const int *v, int len, char *buf)
{
    int i, n = 0;
    if (len == 0) { sprintf(buf, "(空)"); return; }
    for (i = 0; i < len; i++) {
        if (i > 0) buf[n++] = ' ';
        n += sprintf(buf + n, "%d", v[i]);
    }
    buf[n] = '\0';
}

static int isAsc(const int *v, int len)
{
    int i;
    for (i = 1; i < len; i++) if (v[i - 1] >= v[i]) return 0;
    return 1;
}

static void rightRotate(AVLTree *a)
{
    AVLTree b = (*a)->l;
    (*a)->l = b->r;
    b->r = *a;
    *a = b;
}

static void leftRotate(AVLTree *a)
{
    AVLTree b = (*a)->r;
    (*a)->r = b->l;
    b->l = *a;
    *a = b;
}

/* 只按 BST 规则插入，不做平衡调整（用于普通 BST 对照） */
static int bstInsert(AVLTree *t, int key)
{
    if (*t == NULL) { *t = mk(key, NULL, NULL); return 1; }
    if (key == (*t)->key) return 0;
    if (key < (*t)->key) return bstInsert(&(*t)->l, key);
    return bstInsert(&(*t)->r, key);
}

/* AVL 插入。grew 是出参：返回时指示「以 *t 为根的子树是否长高了」。
   这就是教材「bf 变 0 就停止回溯」的实现方式：子树没长高，祖先一律不受影响。 */
static int avlInsert(AVLTree *t, int key, int *grew)
{
    if (*t == NULL) {
        *t = mk(key, NULL, NULL);          /* 新叶子，bf 已在 mk 里置 0 */
        *grew = 1;
        return 1;
    }
    if (key == (*t)->key) { *grew = 0; return 0; }

    if (key < (*t)->key) {
        if (!avlInsert(&(*t)->l, key, grew)) return 0;
        if (!*grew) return 1;              /* ★ 子树没长高，不必再改自己的 bf */
        g_upd++;
        (*t)->bf += 1;                     /* 插入在左子树 */
        if ((*t)->bf == 0) { *grew = 0; g_stop = 1; return 1; }   /* ★ 高度没变，停止回溯 */
        if ((*t)->bf == 1) return 1;       /* 仍平衡但长高了，继续往上 */

        g_zKey = (*t)->key;                /* bf == 2 → 这里就是最低失衡点 A */
        if ((*t)->l->bf == 1) {            /* LL → 右单旋 */
            g_rot = 1;
            rightRotate(t);
            (*t)->bf = 0;
            (*t)->r->bf = 0;
        } else {                           /* LR → 先左旋孩子，再右旋自己 */
            int c = (*t)->l->r->bf;        /* ★ 必须在旋转之前读 */
            g_rot = 3;
            leftRotate(&(*t)->l);
            rightRotate(t);
            (*t)->bf = 0;
            if (c == 1)       { (*t)->l->bf = 0; (*t)->r->bf = -1; }
            else if (c == -1) { (*t)->l->bf = 1; (*t)->r->bf = 0;  }
            else              { (*t)->l->bf = 0; (*t)->r->bf = 0;  }
        }
        *grew = 0;                         /* ★ 旋转后高度复原，祖先不受影响 */
        return 1;
    }

    /* 插入在右子树：与上面完全对称，注意所有符号都反过来 */
    if (!avlInsert(&(*t)->r, key, grew)) return 0;
    if (!*grew) return 1;
    g_upd++;
    (*t)->bf -= 1;
    if ((*t)->bf == 0) { *grew = 0; g_stop = 1; return 1; }
    if ((*t)->bf == -1) return 1;

    g_zKey = (*t)->key;
    if ((*t)->r->bf == -1) {               /* RR → 左单旋 */
        g_rot = 2;
        leftRotate(t);
        (*t)->bf = 0;
        (*t)->l->bf = 0;
    } else {                               /* RL → 先右旋孩子，再左旋自己 */
        int c = (*t)->r->l->bf;
        g_rot = 4;
        rightRotate(&(*t)->r);
        leftRotate(t);
        (*t)->bf = 0;
        if (c == 1)       { (*t)->l->bf = 0; (*t)->r->bf = -1; }
        else if (c == -1) { (*t)->l->bf = 1; (*t)->r->bf = 0;  }
        else              { (*t)->l->bf = 0; (*t)->r->bf = 0;  }
    }
    *grew = 0;
    return 1;
}

static void destroy(AVLTree t)
{
    if (t == NULL) return;
    destroy(t->l);
    destroy(t->r);
    free(t);
}

int main(void)
{
    /* 这个序列会依次触发 LL、RR、RL、LR 四种旋转，共 10 次调整 */
    const int keys[] = { 3, 2, 1, 4, 5, 6, 7, 16, 15, 14, 13, 12, 8, 9 };
    const int n = (int)(sizeof(keys) / sizeof(keys[0]));
    const char *rotName[] = { "无旋转", "LL→右单旋", "RR→左单旋",
                              "LR→双旋", "RL→双旋" };
    AVLTree avl = NULL, bst = NULL;
    char sb[MAXBUF], sq[MAXBUF];
    int seq[64], len, i, grew, h, bad, bal, mism, hBst;
    int cntRot[5] = { 0, 0, 0, 0, 0 };
    int totalUpd = 0, totalStop = 0;
    double lg, v, bound;

    printf("== ① 逐个插入，每步检查四条不变量 ==\n");
    for (i = 0; i < n; i++) {
        g_rot = 0; g_zKey = -1; g_upd = 0; g_stop = 0;
        grew = 0;
        avlInsert(&avl, keys[i], &grew);
        cntRot[g_rot]++;
        totalUpd += g_upd;
        if (g_stop) totalStop++;

        len = 0;
        inorder(avl, seq, &len);
        seqToStr(seq, len, sq);
        shape(avl, sb);
        h = heightOf(avl);
        mism = countBFMismatch(avl);       /* 增量维护的 bf 是否真等于按高度算出的 bf */
        bad = -1;
        bal = checkBal(avl, &bad);

        printf("插入 %2d：%s", keys[i], rotName[g_rot]);
        if (g_rot != 0) printf("（失衡点 %d）", g_zKey);
        printf(" | 回溯更新 %d 个祖先%s\n", g_upd,
               g_stop ? "，其中出现 bf 变 0 提前停止" : "");
        printf("         形态 %s | 高度 %d\n", sb, h);
        printf("         中序 %s | 严格升序？%d  全树|bf|<=1？%d  bf 与实算不符的结点数 %d\n",
               sq, isAsc(seq, len), bal, mism);
    }

    printf("\n== ② 旋转次数统计与最终高度 ==\n");
    printf("  14 次插入共触发 %d 次旋转：LL %d 次、RR %d 次、LR %d 次、RL %d 次（其余 %d 次无旋转）\n",
           cntRot[1] + cntRot[2] + cntRot[3] + cntRot[4],
           cntRot[1], cntRot[2], cntRot[3], cntRot[4], cntRot[0]);
    printf("  回溯累计更新 %d 个祖先的 bf，其中 %d 次插入出现过「bf 变 0 提前停止」\n",
           totalUpd, totalStop);
    h = heightOf(avl);
    lg = 0.0; v = 1.0;
    while (v < (double)(n + 1)) { v *= 2.0; lg += 1.0; }
    printf("  最终高度 = %d，理想平衡下界 ceil(log2(n+1)) = %.0f，两者相等？%d\n",
           h, lg, (double)h == lg);
    lg = 0.0; v = 1.0;
    while (v < (double)(n + 2)) { v *= 2.0; lg += 1.0; }
    bound = 1.44 * lg;
    printf("  AVL 上界 1.44*ceil(log2(n+2)) = %.2f，高度未超上界？%d\n",
           bound, (double)h <= bound);

    printf("\n== ③ 同一序列按普通 BST 插入（不做任何平衡调整）==\n");
    for (i = 0; i < n; i++) bstInsert(&bst, keys[i]);
    hBst = heightOf(bst);
    shape(bst, sb);
    printf("  普通 BST 形态 %s\n", sb);
    printf("  普通 BST 高度 = %d，AVL 高度 = %d，前者是后者的 %.2f 倍\n",
           hBst, h, (double)hBst / (double)h);
    len = 0;
    inorder(bst, seq, &len);
    seqToStr(seq, len, sq);
    printf("  普通 BST 中序 %s | 严格升序？%d（与 AVL 的中序必然相同，因为元素集合相同）\n",
           sq, isAsc(seq, len));

    printf("\n== ④ Fibonacci 树：高度 h 的 AVL 最少要多少个结点 ==\n");
    {
        int fib[11];
        fib[1] = 1;
        fib[2] = 2;
        for (i = 3; i <= 10; i++) fib[i] = fib[i - 1] + fib[i - 2] + 1;
        for (i = 1; i <= 10; i++) {
            lg = 0.0; v = 1.0;
            while (v < (double)(fib[i] + 2)) { v *= 2.0; lg += 1.0; }
            bound = 1.44 * lg;
            printf("  h=%2d  最少结点数 n_h=%4d  1.44*ceil(log2(n_h+2))=%5.2f  h 未超上界？%d\n",
                   i, fib[i], bound, (double)i <= bound);
        }
    }

    printf("\n== ⑤ 「bf 变 0 就停止回溯」的最小演示（上面 14 次插入一次都没触发）==\n");
    {
        const int k2[] = { 60, 40, 80, 90, 70 };
        const int n2 = (int)(sizeof(k2) / sizeof(k2[0]));
        AVLTree t2 = NULL;
        int j, grew2, h2, hPrev = 0;
        for (j = 0; j < n2; j++) {
            g_rot = 0; g_zKey = -1; g_upd = 0; g_stop = 0;
            grew2 = 0;
            avlInsert(&t2, k2[j], &grew2);
            shape(t2, sb);
            h2 = heightOf(t2);
            printf("  插入 %2d：回溯更新 %d 个祖先，提前停止？%s | 形态 %s | 高度 %d（上一步 %d）\n",
                   k2[j], g_upd, g_stop ? "是" : "否", sb, h2, hPrev);
            hPrev = h2;
        }
        printf("  ★ 插入 70 之后：结点 80 的 bf = %d（从 -1 变回 0），结点 60 的 bf = %d，树高 = %d\n",
               t2->r->bf, t2->bf, heightOf(t2));
        printf("    80 的子树高度没变（插入 70 之前也是 2），所以回溯在 80 处就停了：\n");
        printf("    祖先 60 的 bf 一个字节都没改，整棵树的高度也保持不变\n");
        destroy(t2);
    }

    destroy(avl);
    destroy(bst);
    printf("\n三棵树已释放\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define ORDER 3                       /* m = 3，即 2-3 树 */
#define LOWER ((ORDER + 1) / 2 - 1)   /* 非根结点的关键字下界 = ceil(m/2)-1 = 1 */
#define SPLIT ((ORDER + 1) / 2 - 1)   /* 上溢时上移的位置（0-based）= 1 */

typedef struct BTNode {
    int keynum;
    struct BTNode *parent;
    int keys[ORDER];                  /* 开 m 个：上溢的瞬间会有 m 个关键字 */
    struct BTNode *ptr[ORDER + 1];
} BTNode, *BTree;

static int splits = 0, merges = 0, borrows = 0, collapses = 0;

static BTNode *newNode(void) { return (BTNode *)calloc(1, sizeof(BTNode)); }

static int hOf(BTree t) { return t == NULL ? 0 : 1 + hOf(t->ptr[0]); }

static void inorder(BTree t, int *out, int *len)
{
    int i;
    if (t == NULL) return;
    for (i = 0; i < t->keynum; i++) {
        inorder(t->ptr[i], out, len);
        out[(*len)++] = t->keys[i];
    }
    inorder(t->ptr[t->keynum], out, len);
}

static void printSeq(const int *seq, int len)
{
    int i;
    if (len == 0) { printf("(空)"); return; }
    for (i = 0; i < len; i++) { if (i) printf(" "); printf("%d", seq[i]); }
}

static void showKeys(BTNode *p)
{
    int i;
    printf("[");
    for (i = 0; i < p->keynum; i++) printf("%d%s", p->keys[i], i + 1 < p->keynum ? "," : "");
    printf("]");
}

/* 缩进打印：每行一个结点，缩进表示层 */
static void dump(BTree t, int lvl)
{
    int i;
    if (t == NULL) return;
    for (i = 0; i < lvl; i++) printf("    ");
    showKeys(t);
    printf("\n");
    for (i = 0; i <= t->keynum; i++) dump(t->ptr[i], lvl + 1);
}

/* 查找：返回所在层（根是第 1 层），*visited 是访问过的结点数 = 磁盘访问次数 */
static int btreeSearch(BTree t, int key, int *visited)
{
    int i, lvl = 1;
    *visited = 0;
    while (t != NULL) {
        (*visited)++;
        for (i = 0; i < t->keynum && key > t->keys[i]; i++) ;
        if (i < t->keynum && t->keys[i] == key) return lvl;
        t = t->ptr[i];
        lvl++;
    }
    return 0;
}

static void insertKey(BTree *root, int key)
{
    BTNode *p = *root, *q = NULL, *s;
    int i, j, depth = 0;
    while (p != NULL) {                          /* ① 一路走到最底层 */
        q = p; depth++;
        for (i = 0; i < p->keynum && p->keys[i] < key; i++) ;
        p = p->ptr[i];
    }
    if (*root == NULL) {                         /* 空树：新建根 */
        *root = newNode();
        (*root)->keys[0] = key;
        (*root)->keynum = 1;
        printf("  插入 %2d：树为空 → 新建根 ", key); showKeys(*root);
        printf("，h=1，本次分裂 0 次\n");
        return;
    }
    for (i = 0; i < q->keynum && q->keys[i] < key; i++) ;
    for (j = q->keynum; j > i; j--) { q->keys[j] = q->keys[j - 1]; q->ptr[j + 1] = q->ptr[j]; }
    q->keys[i] = key; q->ptr[i + 1] = NULL; q->keynum++;
    printf("  插入 %2d：走到第 %d 层的 ", key, depth); showKeys(q);
    if (q->keynum <= ORDER - 1) { printf(" → keynum=%d <= m-1=%d，不上溢，本次分裂 0 次\n", q->keynum, ORDER - 1); return; }
    printf(" → keynum=%d > m-1=%d，上溢！", q->keynum, ORDER - 1);
    p = q;
    { int before = splits;
      while (p != NULL && p->keynum > ORDER - 1) {
          int up = p->keys[SPLIT];
          s = newNode();
          for (i = SPLIT + 1, j = 0; i < p->keynum; i++, j++) {
              s->keys[j] = p->keys[i]; s->ptr[j] = p->ptr[i];
              if (s->ptr[j]) s->ptr[j]->parent = s;
          }
          s->ptr[j] = p->ptr[p->keynum];
          if (s->ptr[j]) s->ptr[j]->parent = s;
          s->keynum = p->keynum - SPLIT - 1;
          p->keynum = SPLIT;
          s->parent = p->parent;
          splits++;
          if (p->parent == NULL) {
              BTNode *nr = newNode();
              nr->keys[0] = up; nr->keynum = 1; nr->ptr[0] = p; nr->ptr[1] = s;
              p->parent = nr; s->parent = nr; *root = nr;
              printf("%skeys[%d]=%d 上移成新根 → 树长高到 h=%d",
                     splits > before + 1 ? "，接着 " : " ", SPLIT, up, hOf(*root));
              p = NULL;
          } else {
              BTNode *fa = p->parent; int k;
              for (k = 0; k <= fa->keynum; k++) if (fa->ptr[k] == p) break;
              for (i = fa->keynum; i > k; i--) { fa->keys[i] = fa->keys[i - 1]; fa->ptr[i + 1] = fa->ptr[i]; }
              fa->keys[k] = up; fa->ptr[k + 1] = s; fa->keynum++;
              printf(" keys[%d]=%d 上移到父结点", SPLIT, up);
              p = fa;
          }
      }
      printf("，本次分裂 %d 次\n", splits - before);
    }
}

static int findKey(BTree t, int key, BTNode **node, int *idx)
{
    int i;
    while (t != NULL) {
        for (i = 0; i < t->keynum && key > t->keys[i]; i++) ;
        if (i < t->keynum && t->keys[i] == key) { *node = t; *idx = i; return 1; }
        t = t->ptr[i];
    }
    return 0;
}

static void deleteKey(BTree *root, int key)
{
    BTNode *p, *fa, *left, *right;
    int idx, i, sibIdx, base, lower;
    if (!findKey(*root, key, &p, &idx)) { printf("  删除 %2d：不存在\n", key); return; }
    if (p->ptr[idx + 1] != NULL) {               /* 不在最底层 → 用后继替换 */
        BTNode *q = p->ptr[idx + 1];
        while (q->ptr[0] != NULL) q = q->ptr[0];
        printf("  删除 %2d：不在最底层 → 用后继 %d 替换，转化成删最底层\n", key, q->keys[0]);
        p->keys[idx] = q->keys[0]; p = q; idx = 0;
    } else {
        printf("  删除 %2d：就在最底层结点 ", key); showKeys(p); printf(" 中\n");
    }
    for (i = idx; i < p->keynum - 1; i++) { p->keys[i] = p->keys[i + 1]; p->ptr[i + 1] = p->ptr[i + 2]; }
    p->keynum--;
    while (p != NULL) {
        lower = (p->parent == NULL) ? 1 : LOWER;
        if (p->keynum >= lower || p->parent == NULL) break;
        fa = p->parent;
        for (sibIdx = 0; sibIdx <= fa->keynum; sibIdx++) if (fa->ptr[sibIdx] == p) break;
        left  = (sibIdx > 0)          ? fa->ptr[sibIdx - 1] : NULL;
        right = (sibIdx < fa->keynum) ? fa->ptr[sibIdx + 1] : NULL;
        printf("    下溢：keynum=%d < 下界 %d，左兄弟 ", p->keynum, lower);
        if (left) showKeys(left); else printf("(无)");
        printf("（keynum=%d）右兄弟 ", left ? left->keynum : -1);
        if (right) showKeys(right); else printf("(无)");
        printf("（keynum=%d）", right ? right->keynum : -1);
        if (left != NULL && left->keynum > lower) {
            borrows++;
            printf(" → 左兄弟够，借一个\n");
            for (i = p->keynum; i >= 1; i--) p->keys[i] = p->keys[i - 1];
            for (i = p->keynum + 1; i >= 1; i--) p->ptr[i] = p->ptr[i - 1];
            p->keys[0] = fa->keys[sibIdx - 1];
            p->ptr[0] = left->ptr[left->keynum];
            if (p->ptr[0]) p->ptr[0]->parent = p;
            fa->keys[sibIdx - 1] = left->keys[left->keynum - 1];
            left->keynum--; p->keynum++;
            break;
        } else if (right != NULL && right->keynum > lower) {
            borrows++;
            printf(" → 右兄弟够，借一个\n");
            p->keys[p->keynum] = fa->keys[sibIdx];
            p->ptr[p->keynum + 1] = right->ptr[0];
            if (p->ptr[p->keynum + 1]) p->ptr[p->keynum + 1]->parent = p;
            p->keynum++;
            fa->keys[sibIdx] = right->keys[0];
            for (i = 0; i < right->keynum - 1; i++) { right->keys[i] = right->keys[i + 1]; right->ptr[i] = right->ptr[i + 1]; }
            right->ptr[right->keynum - 1] = right->ptr[right->keynum];
            right->keynum--;
            break;
        } else if (left != NULL) {
            merges++;
            printf(" → 谁都不够，与左兄弟合并\n");
            base = left->keynum;
            left->keys[base] = fa->keys[sibIdx - 1];
            for (i = 0; i < p->keynum; i++) left->keys[base + 1 + i] = p->keys[i];
            left->keynum = base + 1 + p->keynum;
            for (i = 0; i <= p->keynum; i++) {
                left->ptr[base + 1 + i] = p->ptr[i];
                if (left->ptr[base + 1 + i]) left->ptr[base + 1 + i]->parent = left;
            }
            free(p);
            for (i = sibIdx - 1; i < fa->keynum - 1; i++) { fa->keys[i] = fa->keys[i + 1]; fa->ptr[i + 1] = fa->ptr[i + 2]; }
            fa->keynum--;
            p = fa;                              /* 父结点可能也下溢，继续往上 */
        } else {
            merges++;
            printf(" → 谁都不够，与右兄弟合并\n");
            base = p->keynum;
            p->keys[base] = fa->keys[sibIdx];
            for (i = 0; i < right->keynum; i++) p->keys[base + 1 + i] = right->keys[i];
            p->keynum = base + 1 + right->keynum;
            for (i = 0; i <= right->keynum; i++) {
                p->ptr[base + 1 + i] = right->ptr[i];
                if (p->ptr[base + 1 + i]) p->ptr[base + 1 + i]->parent = p;
            }
            free(right);
            for (i = sibIdx; i < fa->keynum - 1; i++) { fa->keys[i] = fa->keys[i + 1]; fa->ptr[i + 1] = fa->ptr[i + 2]; }
            fa->keynum--;
            p = fa;
        }
    }
    if (*root != NULL && (*root)->keynum == 0) {  /* 根塌缩 → 树变矮 */
        BTNode *old = *root;
        *root = (old->ptr[0] != NULL) ? old->ptr[0] : NULL;
        if (*root) (*root)->parent = NULL;
        free(old);
        collapses++;
        printf("    根的关键字数变成 0 → 根塌缩，树变矮\n");
    }
}

/* 合法性检查：关键字升序、keynum 在范围内、所有叶子同层 */
static void check(BTree t, int lvl, int *leafLvl, int *bad)
{
    int i, lower = (t->parent == NULL) ? 1 : LOWER;
    if (t->keynum < lower || t->keynum > ORDER - 1) (*bad)++;
    for (i = 0; i < t->keynum - 1; i++) if (t->keys[i] >= t->keys[i + 1]) (*bad)++;
    if (t->ptr[0] == NULL) {
        if (*leafLvl < 0) *leafLvl = lvl;
        else if (*leafLvl != lvl) (*bad)++;
        return;
    }
    for (i = 0; i <= t->keynum; i++) check(t->ptr[i], lvl + 1, leafLvl, bad);
}

static void destroy(BTree t)
{
    int i;
    if (t == NULL) return;
    for (i = 0; i <= t->keynum; i++) destroy(t->ptr[i]);
    free(t);
}

