#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

#define ORDER 3
#define LEAFMAX (ORDER - 1)      /* 叶子最多 2 个关键字 */

/* 统一结点：isLeaf 区分叶子与索引结点。
   叶子：keys 升序存数据，next 串成有序链表。
   索引：keynum == 孩子个数（★B-树是 孩子数-1），keys[i] = 第 i 棵子树的最小关键字 */
typedef struct BPNode {
    int isLeaf;
    int keynum;
    int keys[ORDER + 1];
    struct BPNode *ptr[ORDER + 1];
    struct BPNode *parent;
    struct BPNode *next;         /* 仅叶子使用 */
} BPNode;

static BPNode *bpNew(int isLeaf)
{
    BPNode *p = (BPNode *)calloc(1, sizeof(BPNode));
    p->isLeaf = isLeaf;
    return p;
}

static int bpSplits = 0, leafSplits = 0, intSplits = 0;

/* 从根往下找 key 应落在的叶子；*acc 统计访问过的结点数 = 磁盘访问次数 */
static BPNode *findLeaf(BPNode *root, int key, int *acc)
{
    BPNode *p = root;
    *acc = 0;
    while (p != NULL) {
        (*acc)++;
        if (p->isLeaf) return p;
        {
            int i = p->keynum - 1;
            while (i > 0 && p->keys[i] > key) i--;   /* 找最后一个 keys[i] <= key 的孩子 */
            p = p->ptr[i];
        }
    }
    return NULL;
}

static void insertIntoParent(BPNode **root, BPNode *left, int upKey, BPNode *right);

static BPNode *splitLeaf(BPNode *leaf)
{
    BPNode *nr = bpNew(1);
    int split = (leaf->keynum + 1) / 2, i;
    for (i = split; i < leaf->keynum; i++) nr->keys[i - split] = leaf->keys[i];
    nr->keynum = leaf->keynum - split;
    leaf->keynum = split;
    nr->next = leaf->next;                 /* ★ 接进叶子链表 */
    leaf->next = nr;
    nr->parent = leaf->parent;
    leafSplits++; bpSplits++;
    return nr;
}

static BPNode *splitInternal(BPNode *fa, int *upKey)
{
    BPNode *nr = bpNew(0);
    int split = (fa->keynum + 1) / 2, i, j;
    *upKey = fa->keys[split];
    for (i = split, j = 0; i < fa->keynum; i++, j++) {
        nr->keys[j] = fa->keys[i];
        nr->ptr[j] = fa->ptr[i];
        nr->ptr[j]->parent = nr;
    }
    nr->keynum = fa->keynum - split;
    fa->keynum = split;
    nr->parent = fa->parent;
    intSplits++; bpSplits++;
    return nr;
}

static void insertIntoParent(BPNode **root, BPNode *left, int upKey, BPNode *right)
{
    BPNode *fa = left->parent;
    int k, i;
    if (fa == NULL) {                      /* left 是根 → 新建根 */
        BPNode *nr = bpNew(0);
        nr->keynum = 2;
        nr->keys[0] = left->keys[0];       /* ★ 索引项 = 子树的最小关键字 */
        nr->keys[1] = upKey;
        nr->ptr[0] = left; nr->ptr[1] = right;
        left->parent = nr; right->parent = nr;
        *root = nr;
        return;
    }
    for (k = 0; k < fa->keynum; k++) if (fa->ptr[k] == left) break;
    for (i = fa->keynum; i > k + 1; i--) { fa->keys[i] = fa->keys[i - 1]; fa->ptr[i] = fa->ptr[i - 1]; }
    fa->keys[k + 1] = upKey;
    fa->ptr[k + 1] = right;
    right->parent = fa;
    fa->keynum++;
    if (fa->keynum <= ORDER) return;
    {
        int up2;
        BPNode *nr = splitInternal(fa, &up2);
        insertIntoParent(root, fa, up2, nr);   /* 递归往上传 */
    }
}

static void bpInsert(BPNode **root, int key)
{
    BPNode *leaf;
    int acc, i, j;
    if (*root == NULL) {
        *root = bpNew(1);
        (*root)->keys[0] = key;
        (*root)->keynum = 1;
        printf("  插入 %2d：树为空 → 新建叶子根 [%d]，h=1\n", key, key);
        return;
    }
    leaf = findLeaf(*root, key, &acc);
    for (i = 0; i < leaf->keynum && leaf->keys[i] < key; i++) ;
    for (j = leaf->keynum; j > i; j--) leaf->keys[j] = leaf->keys[j - 1];
    leaf->keys[i] = key;
    leaf->keynum++;
    printf("  插入 %2d：访问 %d 个结点落到叶子 [", key, acc);
    for (i = 0; i < leaf->keynum; i++) printf("%d%s", leaf->keys[i], i + 1 < leaf->keynum ? "," : "");
    printf("]");
    if (leaf->keynum <= LEAFMAX) { printf(" → 不上溢，h 不变\n"); return; }
    {
        BPNode *nr = splitLeaf(leaf);
        int i2;
        printf(" → 上溢，叶子分裂：左 [");
        for (i2 = 0; i2 < leaf->keynum; i2++) printf("%d%s", leaf->keys[i2], i2 + 1 < leaf->keynum ? "," : "");
        printf("] 右 [");
        for (i2 = 0; i2 < nr->keynum; i2++) printf("%d%s", nr->keys[i2], i2 + 1 < nr->keynum ? "," : "");
        printf("]，★ %d 是**复制**上移（叶子必须保留全部关键字）", nr->keys[0]);
        insertIntoParent(root, leaf, nr->keys[0], nr);
        printf("，本次分裂 1 次\n");
    }
}

static int bpHeight(BPNode *t) { return t == NULL ? 0 : 1 + bpHeight(t->ptr[0]); }

static void bpDump(BPNode *t, int lvl)
{
    int i;
    if (t == NULL) return;
    for (i = 0; i < lvl; i++) printf("    ");
    printf("%s[", t->isLeaf ? "叶 " : "索引");
    for (i = 0; i < t->keynum; i++) printf("%d%s", t->keys[i], i + 1 < t->keynum ? "," : "");
    printf("]%s\n", t->isLeaf && t->next ? " →" : "");
    if (!t->isLeaf) for (i = 0; i < t->keynum; i++) bpDump(t->ptr[i], lvl + 1);
}

/* 沿叶子链表走一遍，收集全部关键字 */
static void leafChain(BPNode *root, int *out, int *len, int *leaves, int *leafLvl)
{
    BPNode *p = root;
    int i, lvl = 1;
    *len = 0; *leaves = 0;
    while (p != NULL && !p->isLeaf) { p = p->ptr[0]; lvl++; }
    *leafLvl = lvl;
    for (; p != NULL; p = p->next) {
        (*leaves)++;
        for (i = 0; i < p->keynum; i++) out[(*len)++] = p->keys[i];
    }
}

/* 性质检查：①索引结点 keynum == 孩子数 ②索引 keys[i] == 第 i 棵子树最小关键字
   ③所有叶子同层 ④叶子内关键字升序。返回违规处个数 */
static int subMin(BPNode *t)
{
    while (t != NULL && !t->isLeaf) t = t->ptr[0];
    return t == NULL ? INT_MAX : t->keys[0];
}

static int bpCheck(BPNode *t, int lvl, int *leafLvl)
{
    int i, bad = 0;
    if (t == NULL) return 0;
    if (t->isLeaf) {
        if (*leafLvl < 0) *leafLvl = lvl;
        else if (*leafLvl != lvl) bad++;
        for (i = 0; i < t->keynum - 1; i++) if (t->keys[i] >= t->keys[i + 1]) bad++;
        return bad;
    }
    for (i = 0; i < t->keynum; i++) {
        if (t->ptr[i] == NULL) bad++;
        else if (subMin(t->ptr[i]) != t->keys[i]) bad++;   /* 索引项必须是子树最小关键字 */
    }
    for (i = 0; i < t->keynum; i++) bad += bpCheck(t->ptr[i], lvl + 1, leafLvl);
    return bad;
}

/* 范围查询：沿叶子链表顺序扫，*random 是定位起点的随机访问次数，*seq 是之后顺着 next 走的次数 */
static int bpRange(BPNode *root, int lo, int hi, int *out, int *olen, int *random, int *seq)
{
    BPNode *p;
    int acc, i, visitedLeaf = 0;
    *olen = 0;
    p = findLeaf(root, lo, &acc);
    *random = acc;
    for (; p != NULL; p = p->next) {
        visitedLeaf++;
        for (i = 0; i < p->keynum; i++) {
            if (p->keys[i] > hi) { *seq = visitedLeaf - 1; return *olen; }
            if (p->keys[i] >= lo) out[(*olen)++] = p->keys[i];
        }
    }
    *seq = visitedLeaf - 1;
    return *olen;
}

static void bpDestroy(BPNode *t)
{
    int i;
    if (t == NULL) return;
    if (!t->isLeaf) for (i = 0; i < t->keynum; i++) bpDestroy(t->ptr[i]);
    free(t);
}

/* ══ 对照组：同一批关键字的 B-树（m=3），只保留插入与范围查询计数 ══ */
#define BTLOWER ((ORDER + 1) / 2 - 1)
#define BTSPLIT ((ORDER + 1) / 2 - 1)

typedef struct BTNode {
    int keynum;
    struct BTNode *parent;
    int keys[ORDER];
    struct BTNode *ptr[ORDER + 1];
} BTNode, *BTree;

static BTNode *btNew(void) { return (BTNode *)calloc(1, sizeof(BTNode)); }

static void btInsert(BTree *root, int key)
{
    BTNode *p = *root, *q = NULL, *s;
    int i, j;
    while (p != NULL) { q = p; for (i = 0; i < p->keynum && p->keys[i] < key; i++) ; p = p->ptr[i]; }
    if (*root == NULL) { *root = btNew(); (*root)->keys[0] = key; (*root)->keynum = 1; return; }
    for (i = 0; i < q->keynum && q->keys[i] < key; i++) ;
    for (j = q->keynum; j > i; j--) { q->keys[j] = q->keys[j - 1]; q->ptr[j + 1] = q->ptr[j]; }
    q->keys[i] = key; q->ptr[i + 1] = NULL; q->keynum++;
    p = q;
    while (p != NULL && p->keynum > ORDER - 1) {
        int up = p->keys[BTSPLIT];
        s = btNew();
        for (i = BTSPLIT + 1, j = 0; i < p->keynum; i++, j++) {
            s->keys[j] = p->keys[i]; s->ptr[j] = p->ptr[i];
            if (s->ptr[j]) s->ptr[j]->parent = s;
        }
        s->ptr[j] = p->ptr[p->keynum];
        if (s->ptr[j]) s->ptr[j]->parent = s;
        s->keynum = p->keynum - BTSPLIT - 1;
        p->keynum = BTSPLIT; s->parent = p->parent;
        if (p->parent == NULL) {
            BTNode *nr = btNew();
            nr->keys[0] = up; nr->keynum = 1; nr->ptr[0] = p; nr->ptr[1] = s;
            p->parent = nr; s->parent = nr; *root = nr; p = NULL;
        } else {
            BTNode *fa = p->parent; int k;
            for (k = 0; k <= fa->keynum; k++) if (fa->ptr[k] == p) break;
            for (i = fa->keynum; i > k; i--) { fa->keys[i] = fa->keys[i - 1]; fa->ptr[i + 1] = fa->ptr[i]; }
            fa->keys[k] = up; fa->ptr[k + 1] = s; fa->keynum++; p = fa;
        }
    }
}

static int btHeight(BTree t) { return t == NULL ? 0 : 1 + btHeight(t->ptr[0]); }

/* 带剪枝的中序范围扫描：*acc 数进入过的结点个数（每个都是一次随机 I/O） */
static void btRange(BTree t, int lo, int hi, int tlo, int thi, int *acc, int *out, int *olen)
{
    int i;
    if (t == NULL) return;
    if ((long long)tlo > hi || (long long)thi < lo) return;   /* 剪枝：子树范围与查询区间无交集 */
    (*acc)++;
    for (i = 0; i < t->keynum; i++) {
        int clo = (i == 0) ? INT_MIN : t->keys[i - 1];
        btRange(t->ptr[i], lo, hi, clo, t->keys[i], acc, out, olen);
        if (t->keys[i] >= lo && t->keys[i] <= hi) out[(*olen)++] = t->keys[i];
    }
    btRange(t->ptr[t->keynum], lo, hi, t->keys[t->keynum - 1], INT_MAX, acc, out, olen);
}

/* 单点查找的访问次数 */
static int btSearch(BTree t, int key, int *acc)
{
    int i, lvl = 1;
    *acc = 0;
    while (t != NULL) {
        (*acc)++;
        for (i = 0; i < t->keynum && key > t->keys[i]; i++) ;
        if (i < t->keynum && t->keys[i] == key) return lvl;
        t = t->ptr[i]; lvl++;
    }
    return 0;
}

static void btDestroy(BTree t)
{
    int i;
    if (t == NULL) return;
    for (i = 0; i <= t->keynum; i++) btDestroy(t->ptr[i]);
    free(t);
}

int main(void)
{
    int keys[7] = { 20, 30, 50, 52, 60, 68, 70 };
    BPNode *bpr = NULL;
    BTree btr = NULL;
    int seq[32], len = 0, leaves = 0, leafLvl = -1, bad, i;

    printf("== ① 逐步插入 {20,30,50,52,60,68,70} 到 3 阶 B+树 ==\n");
    for (i = 0; i < 7; i++) bpInsert(&bpr, keys[i]);
    printf("  最终形态（叶 = 叶子结点，索引 = 非叶结点，→ 表示叶子链表）：\n");
    bpDump(bpr, 1);
    printf("  h=%d，叶子分裂 %d 次、索引结点分裂 %d 次\n", bpHeight(bpr), leafSplits, intSplits);

    printf("\n== ② 五条性质的实测 ==\n");
    leafChain(bpr, seq, &len, &leaves, &leafLvl);
    printf("  沿叶子链表遍历得到 %d 个关键字：", len);
    for (i = 0; i < len; i++) printf("%d%s", seq[i], i + 1 < len ? " " : "");
    printf("\n  叶子结点 %d 个，全部在第 %d 层（h=%d）相符=%d\n", leaves, leafLvl, bpHeight(bpr), leafLvl == bpHeight(bpr));
    {
        int sorted = 1;
        for (i = 0; i < len - 1; i++) if (seq[i] >= seq[i + 1]) sorted = 0;
        printf("  叶子链表严格升序=%d，关键字个数 == 插入个数（%d == 7）=%d\n", sorted, len, len == 7);
    }
    leafLvl = -1;
    bad = bpCheck(bpr, 1, &leafLvl);
    printf("  索引结点「keynum == 孩子数」且「keys[i] == 第 i 棵子树最小关键字」：违规处 %d\n", bad);

    printf("\n== ③ 单点查找：B+树代价恒定 vs B-树随层变化 ==\n");
    for (i = 0; i < 7; i++) btInsert(&btr, keys[i]);
    printf("  B-树形态（h=%d）：根 [52]，孩子 [30]([20],[50]) 与 [68]([60],[70])\n", btHeight(btr));
    for (i = 0; i < len; i++) {
        int accBP = 0, accBT = 0, lvl;
        findLeaf(bpr, seq[i], &accBP);
        lvl = btSearch(btr, seq[i], &accBT);
        printf("  查 %2d：B+树访问 %d 个结点（=h=%d）| B-树在第 %d 层、访问 %d 个结点\n",
               seq[i], accBP, bpHeight(bpr), lvl, accBT);
    }

    printf("\n== ④ 范围查询 [50,68]：这才是 B+树存在的理由 ==\n");
    {
        int out1[16], n1 = 0, rnd = 0, sq = 0;
        int out2[16], n2 = 0, acc2 = 0;
        bpRange(bpr, 50, 68, out1, &n1, &rnd, &sq);
        btRange(btr, 50, 68, INT_MIN, INT_MAX, &acc2, out2, &n2);
        printf("  B+树：定位起点 %d 次随机访问 + 顺着 next 走 %d 次顺序访问 = 共 %d 次\n", rnd, sq, rnd + sq);
        printf("        结果：");
        for (i = 0; i < n1; i++) printf("%d%s", out1[i], i + 1 < n1 ? " " : "");
        printf("\n  B-树：带剪枝的中序遍历，进入过 %d 个结点 = %d 次随机访问\n", acc2, acc2);
        printf("        结果：");
        for (i = 0; i < n2; i++) printf("%d%s", out2[i], i + 1 < n2 ? " " : "");
        int sameOut = (n1 == n2);
        for (i = 0; i < n1 && i < n2; i++) if (out1[i] != out2[i]) sameOut = 0;
        printf("\n  两者结果相同=%d，但 B-树多用了 %d 次访问，而且全是随机 I/O（磁头在盘片上跳跃）\n",
               sameOut, acc2 - (rnd + sq));
    }

    bpDestroy(bpr);
    btDestroy(btr);
    printf("\n两棵树已释放\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define M    13        /* 表长 */
#define P    13        /* 除数：不大于 M 的最大质数 */
#define FREE  0        /* 空槽：查找遇到它就停止 */
#define USED  1
#define GONE  2        /* 懒删除标记：查找要跳过它继续探测 */
#define NK   12

typedef struct { int slot[M]; int flag[M]; } OpenHash;

static void ohInit(OpenHash *h)
{
    int i;
    for (i = 0; i < M; i++) { h->slot[i] = 0; h->flag[i] = FREE; }
}

/* 线性探测插入。trace 记下探测过的位置，返回比较次数（每检查一格算一次） */
static int ohInsert(OpenHash *h, int key, int *trace, int *tlen)
{
    int i, pos, cmp = 0;
    *tlen = 0;
    for (i = 0; i < M; i++) {
        pos = (key % P + i) % M;
        cmp++;
        trace[(*tlen)++] = pos;
        if (h->flag[pos] != USED) {
            h->slot[pos] = key;
            h->flag[pos] = USED;
            return cmp;
        }
    }
    return -1;                     /* 表满，插不进去 */
}

/* 查找。返回正数 = 找到且值是比较次数；负数 = 找不到且绝对值是比较次数 */
static int ohSearch(const OpenHash *h, int key, int *trace, int *tlen)
{
    int i, pos, cmp = 0;
    *tlen = 0;
    for (i = 0; i < M; i++) {
        pos = (key % P + i) % M;
        cmp++;
        trace[(*tlen)++] = pos;
        if (h->flag[pos] == FREE) return -cmp;         /* 空槽 → 停止 */
        if (h->flag[pos] == USED && h->slot[pos] == key) return cmp;
        /* GONE 或 USED 但不等 → 继续探测 */
    }
    return -cmp;
}

/* 失败查找：从散列地址 start 起探测到第一个空槽，返回比较次数 */
static int ohFailProbe(const OpenHash *h, int start)
{
    int i, pos, cmp = 0;
    for (i = 0; i < M; i++) {
        pos = (start + i) % M;
        cmp++;
        if (h->flag[pos] == FREE) return cmp;
    }
    return cmp;
}

/* ---------- 链地址法 ---------- */
typedef struct CNode { int key; struct CNode *next; } CNode;

static CNode *buckets[M];

static void chInit(void)
{
    int i;
    for (i = 0; i < M; i++) buckets[i] = NULL;
}

/* 尾插：保持输入次序（换成头插链上次序会整个反过来） */
static void chInsert(int key)
{
    int h = key % P;
    CNode *p = (CNode *)malloc(sizeof(CNode));
    CNode *q;
    p->key = key;
    p->next = NULL;
    if (buckets[h] == NULL) { buckets[h] = p; return; }
    q = buckets[h];
    while (q->next != NULL) q = q->next;
    q->next = p;
}

static int chSearch(int key)
{
    CNode *q = buckets[key % P];
    int cmp = 0;
    while (q != NULL) {
        cmp++;
        if (q->key == key) return cmp;
        q = q->next;
    }
    return -cmp;                  /* 负数：没找到，绝对值是比较次数 */
}

static int chLen(int h)
{
    CNode *q = buckets[h];
    int n = 0;
    while (q != NULL) { n++; q = q->next; }
    return n;
}

static void chDestroy(void)
{
    int i;
    for (i = 0; i < M; i++) {
        CNode *q = buckets[i];
        while (q != NULL) { CNode *t = q; q = q->next; free(t); }
        buckets[i] = NULL;
    }
}

/* 打印一串探测位置 */
static void printTrace(const int *trace, int len)
{
    int i;
    for (i = 0; i < len; i++) printf("%d%s", trace[i], i + 1 < len ? "," : "");
}

int main(void)
{
    static int keys[NK] = { 19, 14, 23, 1, 68, 20, 84, 27, 55, 11, 10, 79 };
    OpenHash oh;
    int trace[M], tlen, i, cmp, sumS, sumF, empt, r;
    double aslOpenS, aslOpenF;      /* 线性探测的成功/失败 ASL，供后面几段做真对照 */

    printf("== ① 线性探测开放定址：逐个关键字的探测序列（m=%d, p=%d, H(key)=key mod p）==\n", M, P);
    ohInit(&oh);
    sumS = 0;
    for (i = 0; i < NK; i++) {
        cmp = ohInsert(&oh, keys[i], trace, &tlen);
        sumS += cmp;
        printf("  key=%d H=%d → 探测 ", keys[i], keys[i] % P);
        printTrace(trace, tlen);
        printf(" 比较 %d 次，存入 [%d]\n", cmp, trace[tlen - 1]);
    }

    printf("\n== ② 建成的表与成功 ASL ==\n  ");
    empt = 0;
    for (i = 0; i < M; i++) {
        if (i > 0) printf(" ");
        if (oh.flag[i] == FREE) { printf("[%d]=空", i); empt++; }
        else printf("[%d]=%d", i, oh.slot[i]);
    }
    printf("\n  空槽个数 = %d，装填因子 α = %d/%d = %.4f\n", empt, NK, M, (double)NK / M);
    printf("  逐个关键字的成功比较次数：");
    for (i = 0; i < NK; i++) {
        r = ohSearch(&oh, keys[i], trace, &tlen);
        printf("%d→%d%s", keys[i], r, i + 1 < NK ? " " : "");
    }
    aslOpenS = (double)sumS / NK;
    printf("\n  Σ = %d，ASL_成功 = %d/%d = %.4f\n", sumS, sumS, NK, aslOpenS);

    printf("\n== ③ 失败 ASL：对 %d 个散列地址分别算 ==\n  ", M);
    sumF = 0;
    for (i = 0; i < M; i++) {
        cmp = ohFailProbe(&oh, i);
        sumF += cmp;
        printf("%d%s", cmp, i + 1 < M ? "," : "");
    }
    aslOpenF = (double)sumF / M;
    printf("\n  Σ = %d，ASL_失败 = %d/%d = %.4f\n", sumF, sumF, M, aslOpenF);
    printf("  ★ 失败(%.4f) 是成功(%.4f) 的 %.2f 倍 —— 堆积的代价主要由失败查找承担\n",
           aslOpenF, aslOpenS, aslOpenF / aslOpenS);

    printf("\n== ④ 链地址法：同一组关键字（尾插，保持输入次序）==\n");
    chInit();
    for (i = 0; i < NK; i++) chInsert(keys[i]);
    {
        int nonEmpty = 0;
        for (i = 0; i < M; i++) {
            int len = chLen(i);
            if (len == 0) continue;
            nonEmpty++;
            printf("  桶 %2d: ", i);
            {
                CNode *q = buckets[i];
                while (q != NULL) { printf("%d%s", q->key, q->next != NULL ? " → " : ""); q = q->next; }
                printf("（链长 %d）\n", len);
            }
        }
        printf("  其余 %d 个桶为空（链长 0）\n", M - nonEmpty);
    }
    sumS = 0;
    printf("  逐个关键字的成功比较次数：");
    for (i = 0; i < NK; i++) {
        cmp = chSearch(keys[i]);
        sumS += cmp;
        printf("%d→%d%s", keys[i], cmp, i + 1 < NK ? " " : "");
    }
    printf("\n  Σ = %d，ASL_成功 = %d/%d = %.4f（线性探测是 %.4f，链地址法更优 = %d）\n",
           sumS, sumS, NK, (double)sumS / NK, aslOpenS, (double)sumS / NK < aslOpenS);
    sumF = 0;
    for (i = 0; i < M; i++) sumF += chLen(i);
    printf("  ASL_失败（只数关键字比较）= Σ链长/%d = %d/%d = %.4f\n", M, sumF, M, (double)sumF / M);
    printf("  ASL_失败（含与 NULL 的最后一次比较）= Σ(链长+1)/%d = %d/%d = %.4f\n",
           M, sumF + M, M, (double)(sumF + M) / M);
    chDestroy();

    printf("\n== ⑤ 装填因子的影响：只插前 6 个关键字（α = 6/%d = %.4f）==\n", M, 6.0 / M);
    {
        OpenHash oh2;
        int s6 = 0, f6 = 0, used6 = 0, n6 = 6;
        double a6, a6f;
        ohInit(&oh2);
        for (i = 0; i < n6; i++) {
            cmp = ohInsert(&oh2, keys[i], trace, &tlen);
            s6 += cmp;
        }
        printf("  表：");
        for (i = 0; i < M; i++) {
            if (oh2.flag[i] == USED) { if (used6 > 0) printf(" "); printf("[%d]=%d", i, oh2.slot[i]); used6++; }
        }
        printf("，其余 %d 格为空\n", M - used6);
        for (i = 0; i < M; i++) f6 += ohFailProbe(&oh2, i);
        a6 = (double)s6 / n6;
        a6f = (double)f6 / M;
        printf("  Σ成功 = %d，ASL_成功 = %d/%d = %.4f（α=%.4f 时是 %.4f）\n", s6, s6, n6, a6, (double)NK / M, aslOpenS);
        printf("  Σ失败 = %d，ASL_失败 = %d/%d = %.4f（α=%.4f 时是 %.4f）\n", f6, f6, M, a6f, (double)NK / M, aslOpenF);
        printf("  ★ α 从 %.4f 涨到 %.4f（翻 %.2f 倍），失败 ASL 涨了 %.2f 倍、成功只涨了 %.2f 倍\n",
               (double)n6 / M, (double)NK / M, ((double)NK / M) / ((double)n6 / M),
               aslOpenF / a6f, aslOpenS / a6);
        printf("  → 失败查找对 α 敏感得多，这正是「散列表要及时扩容」的依据\n");
    }

    printf("\n== ⑥ 删除：为什么开放定址必须用懒删除 ==\n");
    ohInit(&oh);
    for (i = 0; i < NK; i++) ohInsert(&oh, keys[i], trace, &tlen);
    cmp = ohSearch(&oh, 55, trace, &tlen);
    printf("  删除前查 55：H=%d，探测 ", 55 % P);
    printTrace(trace, tlen);
    printf(" → %s，比较 %d 次\n", cmp > 0 ? "找到" : "找不到", cmp > 0 ? cmp : -cmp);

    oh.flag[4] = FREE;                       /* 真删除 27（它在 [4]） */
    cmp = ohSearch(&oh, 55, trace, &tlen);
    printf("  真删除 27（[4] 变空槽）后查 55：探测 ");
    printTrace(trace, tlen);
    printf(" → %s，比较 %d 次\n", cmp > 0 ? "找到" : "★ 找不到（探测链被切断了）", cmp > 0 ? cmp : -cmp);

    ohInit(&oh);
    for (i = 0; i < NK; i++) ohInsert(&oh, keys[i], trace, &tlen);
    oh.flag[4] = GONE;                       /* 懒删除 27 */
    cmp = ohSearch(&oh, 55, trace, &tlen);
    printf("  懒删除 27（[4] 标成 GONE）后查 55：探测 ");
    printTrace(trace, tlen);
    printf(" → %s，比较 %d 次\n", cmp > 0 ? "找到（跳过已删格子继续探测）" : "找不到", cmp > 0 ? cmp : -cmp);
    printf("  链地址法没有这个问题：摘掉链表里的一个结点不会断开任何路径，可以直接真删\n");

    return 0;
}
